std::shared_ptr<::cw::lib::Surface> load_card_background(
    const ::cw::lib::String& path, bool mask, bool wx, bool scaled,
    bool noscale, std::optional<::cw::lib::Integer> up)
{
    const auto key = ::cw::lib::encoding::path_to_utf8(std::filesystem::u8path(path).stem());
    // Py と同様、HOLD/PENALTY は中央を、プレミアの印は右上をマスクする。
    const bool overlay = key == "HOLD" || key == "PENALTY";
    const bool premium = key == "PREMIER" || key == "RARE";
    mask = mask || overlay || premium;
    const ::cw::lib::String maskpos = overlay ? "center" : premium ? "right" : "";
    const auto scale = up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt;
    if (wx) return ::cw::util::load_wxbmp(path, mask, {},
        maskpos.empty() ? ::cw::lib::Value{} : ::cw::lib::Value(maskpos),
        std::nullopt, true, scaled, noscale, scale);
    return ::cw::util::load_image(path, mask, {0, 0}, std::nullopt, true, false,
        scaled, noscale, scale, false,
        maskpos.empty() ? std::nullopt : std::optional<::cw::lib::String>(maskpos));
}

