std::optional<::cardwirth::platform::StorageStat> user_or_native_stat(
    const std::filesystem::path& path)
{
    if (::cardwirth::platform::is_mounted_user_path(path))
        return ::cardwirth::platform::stat_mounted_user_path(path);
    std::error_code ec;
    if (!std::filesystem::exists(path, ec))
        return ec ? std::nullopt
                  : std::optional<::cardwirth::platform::StorageStat>(
                        ::cardwirth::platform::StorageStat{});
    ::cardwirth::platform::StorageStat result;
    result.type = std::filesystem::is_regular_file(path, ec)
        ? ::cardwirth::platform::StorageEntryType::File
        : std::filesystem::is_directory(path, ec)
            ? ::cardwirth::platform::StorageEntryType::Directory
            : ::cardwirth::platform::StorageEntryType::Other;
    return ec ? std::nullopt : std::optional(result);
}

bool user_or_native_mkdir(const std::filesystem::path& path)
{
    if (::cardwirth::platform::is_mounted_user_path(path))
        return ::cardwirth::platform::make_mounted_user_directory(path, true);
    std::error_code ec;
    std::filesystem::create_directories(path, ec);
    return !ec;
}

std::vector<std::filesystem::path> user_or_native_list(
    const std::filesystem::path& path)
{
    if (::cardwirth::platform::is_mounted_user_path(path)) {
        std::vector<std::filesystem::path> result;
        if (const auto entries = ::cardwirth::platform::list_mounted_user_path(path))
            for (const auto& entry : *entries) result.push_back(entry.path);
        return result;
    }
    std::vector<std::filesystem::path> result;
    std::error_code ec;
    for (std::filesystem::directory_iterator it(path, ec), end; !ec && it != end;
         it.increment(ec)) result.push_back(it->path());
    return result;
}

bool user_or_native_remove_tree(const std::filesystem::path& path)
{
    if (::cardwirth::platform::is_mounted_user_path(path))
        return ::cardwirth::platform::remove_mounted_user_path(path, true);
    std::error_code ec;
    std::filesystem::remove_all(path, ec);
    return !ec;
}

