bool apply_native_cursor(const ::cw::lib::String& name)
{
#if CW_SETTING_HAS_SDL3
    std::scoped_lock lock(g_cursor_mutex);
    if (const auto found = g_named_native_cursors.find(name);
        found != g_named_native_cursors.end() && found->second) {
        return SDL_SetCursor(found->second);
    }
    if (const auto found = g_native_cursors.find(name);
        found != g_native_cursors.end() && found->second) {
        return SDL_SetCursor(found->second);
    }
#else
    (void)name;
#endif
    return false;
}

bool ensure_native_cursor(const ::cw::lib::String& name)
{
    if (apply_native_cursor(name)) return true;
    (void)create_native_cursor(name, {});
    return apply_native_cursor(name);
}

std::optional<DirectionCursorImage> pygame_cursor_fallback(const ::cw::lib::String& name)
{
    using namespace pygame_cursor_data;
    const std::array<std::uint8_t, 32>* data = nullptr;
    const std::array<std::uint8_t, 32>* mask = nullptr;
    DirectionCursorImage result;
    if (name == "CURSOR_DIAMOND") { data = &diamond_data; mask = &diamond_mask; result.hotspot = {7, 7}; }
    else if (name == "CURSOR_BROKEN_X") { data = &broken_x_data; mask = &broken_x_mask; result.hotspot = {7, 7}; }
    else if (name == "CURSOR_TRI_LEFT") { data = &tri_left_data; mask = &tri_left_mask; result.hotspot = {1, 1}; }
    else if (name == "CURSOR_TRI_RIGHT") { data = &tri_right_data; mask = &tri_right_mask; result.hotspot = {14, 1}; }
    else return std::nullopt;
    // pygame/SDL の単色マスクと同様、各行は上位ビットから扱う。mask=0
    // は透明、mask=1/data=1 は黒、mask=1/data=0 は白となる。
    // これら四つの Py リソースには反転ビットがないため、RGBA で正確に表せる。
    result.surface = std::make_shared<::cw::lib::Surface>();
    result.surface->size = {16, 16};
    result.surface->rgba.assign(16 * 16 * 4, 0);
    for (int y = 0; y < 16; ++y) for (int x = 0; x < 16; ++x) {
        const auto index = static_cast<std::size_t>(y * 2 + x / 8);
        const auto bit = 0x80u >> (x % 8);
        if (((*mask)[index] & bit) == 0) continue;
        const auto offset = static_cast<std::size_t>((y * 16 + x) * 4);
        const std::uint8_t color = ((*data)[index] & bit) ? 0 : 255;
        for (int c = 0; c < 3; ++c) result.surface->rgba[offset + c] = color;
        result.surface->rgba[offset + 3] = 255;
    }
    return result;
}

DirectionCursorImage direction_cursor_fallback(bool forward)
{
    static constexpr const char* rows[]={
        "", "", "", "",
        "          XXXX",
        "          X..X",
        "          X..X",
        " XXXXXXXXXX..XXXX",
        " X..............X",
        "X...............X",
        " XXXXXXXXXX..X..XX",
        "          X..X..X.X",
        "          X..X..X.X",
        "          X.......X",
        "          X.......X",
        "           X.....X",
        "           X.....X",
        "            XXXXX",
        "", "", "", "", "", ""
    };
    DirectionCursorImage result;
    result.surface=std::make_shared<::cw::lib::Surface>();
    result.surface->size={24,24};result.surface->rgba.assign(24*24*4,0);
    result.hotspot={forward?23:0,9};
    for(int y=0;y<24;++y) for(int x=0;rows[y][x];++x) {
        if(rows[y][x]!='X' && rows[y][x]!='.') continue;
        const auto offset=(y*24+(forward?23-x:x))*4;
        const std::uint8_t value=rows[y][x]=='X'?0:255;
        for(int channel=0;channel<3;++channel) result.surface->rgba[offset+channel]=value;
        result.surface->rgba[offset+3]=255;
    }
    return result;
}

