void LazyResource::initialize(::cw::lib::Callback arg_func, std::vector<::cw::lib::Value> arg_args, ::cw::lib::ValueMap arg_kwargs)
{
    m_callback = std::move(arg_func); m_arglist = std::move(arg_args); m_kwargmap = std::move(arg_kwargs); m_load = false; m_failure = false; m__res.reset();
    auto args = std::make_shared<::cw::data::VariantSequence>(); args->m_values = m_arglist; m_args = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(args));
    auto kwargs = std::make_shared<::cw::data::VariantSequence>(); for (const auto& [key, value] : m_kwargmap) { kwargs->m_values.emplace_back(key); kwargs->m_values.emplace_back(value); } m_kwargs = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(kwargs));
    // compat::ValueにFunction型がないため、m_funcは「callback有り」の印を保持する。
    m_func = m_callback ? ::cw::lib::Value("callback") : ::cw::lib::Value{};
}

void LazyResource::clear()
{
    m__res.reset(); m_load = false;
    // Python版clear()はfailureフラグを保持するため、同じ壊れたリソースを
    // 再試行してもResourceTable側の失敗扱いを維持する。
}

::cw::lib::Value LazyResource::get_res()
{
    if (!m_load) {
        // Py との意図的な実行境界の差として、C++ に再帰上限を設ける。CPython
        // は C スタックを使い切る前に RecursionError を
        // 出すが、ネイティブにはその保護がない。 Py 3.8 の既定の 1000
        // フレームでは、参照検証の入口四フレームを除き get_res
        // とコールバックの 498 組が許されるため、同じ組数で制限する。
        // Python の他の呼び出し階層や sys.setrecursionlimit
        // で上限は変わるが、共通ネイティブの制限はホストのスタックに
        // 依存させない。 今回の試行へ入る前に例外を出し、親のコール
        // バックが Py と同様に失敗をキャッシュできるようにする。
        static thread_local std::size_t callback_depth = 0;
        constexpr std::size_t callback_limit = (1000 - 4) / 2;
        if (callback_depth >= callback_limit)
            throw std::runtime_error("LazyResource maximum recursion depth exceeded");
        struct CallbackDepth {
            std::size_t& depth;
            explicit CallbackDepth(std::size_t& value) : depth(value) { ++depth; }
            ~CallbackDepth() { --depth; }
        } depth_scope(callback_depth);
        ::cw::lib::KeywordArguments kwargs;
        for (const auto& [key, value] : m_kwargmap) kwargs.emplace(key, value);
        try {
            if (!m_callback) throw std::runtime_error("LazyResource has no callback");
            m__res = m_callback(m_arglist, kwargs);
        } catch (...) {
            m_failure = true;
            std::fprintf(stderr, "LazyResource: resource callback failed.\n");
        }
        m_load = true;
    }
    // Py は None を返すコールバックも含め、試行のキャッシュ後にアサートす
    // る。 Release でも失敗の規則を維持するため、C++ の例外を使う。
    if (!m__res || m__res->is_none())
        throw std::runtime_error("LazyResource result is None");
    return *m__res;
}

