void LocalSetting::init()
{
    m_important_draw = false; m_important_draw_init = m_important_draw;
    m_important_font = false; m_important_font_init = m_important_font;
    m_mwincolour = {0, 0, 80, 180}; m_mwincolour_init = ::cw::lib::Bytes{0, 0, 80, 180};
    m_mwinframecolour = {128, 0, 0, 255}; m_mwinframecolour_init = ::cw::lib::Bytes{128, 0, 0, 255};
    m_allengineframecolour = m_mwinframecolour;
    m_blwincolour = {80, 80, 80, 180}; m_blwincolour_init = ::cw::lib::Bytes{80, 80, 80, 180};
    m_blwinframecolour = {128, 128, 128, 255}; m_blwinframecolour_init = ::cw::lib::Bytes{128, 128, 128, 255};
    m_curtaincolour = ::cw::lib::Bytes{0, 0, 80, 128}; m_curtaincolour_init = ::cw::lib::Bytes{0, 0, 80, 128};
    m_blcurtaincolour = ::cw::lib::Bytes{0, 0, 0, 192}; m_blcurtaincolour_init = ::cw::lib::Bytes{0, 0, 0, 192};
    m_fullscreenbackgroundtype = 2; m_fullscreenbackgroundtype_init = m_fullscreenbackgroundtype;
    m_fullscreenbackgroundfile = "Resource/Image/Dialog/PAD"; m_fullscreenbackgroundfile_init = m_fullscreenbackgroundfile;
    m_decorationfont = false; m_decorationfont_init = m_decorationfont;
    m_bordering_cardname = true; m_bordering_cardname_init = m_bordering_cardname;
    m_fontsmoothing_message = false; m_fontsmoothing_message_init = m_fontsmoothing_message;
    // Python との意図的な差異として、全プラットフォームでメニュー・キャラ
    // クターカード名を既定で平滑化する。 明示的に保存されたオフ設定は尊重する。
    m_fontsmoothing_cardname = true; m_fontsmoothing_cardname_init = m_fontsmoothing_cardname;
    m_fontsmoothing_statusbar = true; m_fontsmoothing_statusbar_init = m_fontsmoothing_statusbar;
    // Windows の EnumFontFamiliesExW と共通のフォントディレクトリー
    // 走査は、 リソース表の初期化時に Resource::get_fontpaths が行う。
    m_basefont = {{"gothic", ""}, {"uigothic", ""}, {"mincho", ""}, {"pmincho", ""}, {"pgothic", ""}};
    m_basefont_init_typed = m_basefont;
    m_fonttypes_typed = local_fonttype_defaults(); m_fonttypes_init_typed = m_fonttypes_typed;
    m_fonttypes.clear();
    for (const auto& [key, value] : m_fonttypes_typed) m_fonttypes.emplace(key, ::cw::lib::Value(std::get<0>(value)));
    m_msg_exfonts = local_msg_exfont_defaults(); m_msg_exfonts_init_typed = m_msg_exfonts;
    // Valueは生成コードとのABI互換用であり、表の実データは上の型付き
    // mapに保持する。UI側が参照するbool既定値だけはValueへも入れる。
    m_basefont_init = ::cw::lib::Value("initialized");
    m_fonttypes_init = ::cw::lib::Value("initialized");
    m_msg_exfonts_init = ::cw::lib::Value("initialized");
}

void LocalSetting::load(::cw::lib::Value arg_data)
{
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_data.storage());
    if (!object || !*object) return;
    load(std::dynamic_pointer_cast<::cw::data::CWPyElement>(*object));
}

void LocalSetting::load(std::shared_ptr<::cw::data::CWPyElement> arg_data)
{
    if (!arg_data) return;
    // Python版はload毎にinitの浅いコピーを作る。型付きmapは値そのものを
    // 保持するので、ここでは明示的にコピーしてからXML上書きを行う。
    m_basefont = m_basefont_init_typed;
    m_fonttypes_typed = m_fonttypes_init_typed;
    m_msg_exfonts = m_msg_exfonts_init_typed;
    m_fonttypes.clear();
    for (const auto& [key, value] : m_fonttypes_typed) m_fonttypes.emplace(key, ::cw::lib::Value(std::get<0>(value)));

    m_important_draw = ::cw::setting::XmlReader(*arg_data).getbool(".", ::cw::lib::Value("importantdrawing"), false);
    m_important_font = ::cw::setting::XmlReader(*arg_data).getbool(".", ::cw::lib::Value("importantfont"), false);
    auto color = [&](const char* tag, const auto& fallback) {
        const auto r = ::cw::setting::XmlReader(*arg_data).getint(tag, ::cw::lib::Value("red"), std::get<0>(fallback));
        const auto g = ::cw::setting::XmlReader(*arg_data).getint(tag, ::cw::lib::Value("green"), std::get<1>(fallback));
        const auto b = ::cw::setting::XmlReader(*arg_data).getint(tag, ::cw::lib::Value("blue"), std::get<2>(fallback));
        const auto a = ::cw::setting::XmlReader(*arg_data).getint(tag, ::cw::lib::Value("alpha"), std::get<3>(fallback));
        return Setting::wrap_colorvalue(r, g, b, a);
    };
    // Python の load と同様、欠落した XML 項目にはこの LocalSetting
    // の初期スナップショットを使う。 前回の読み込み値や固定の全体値は使わない。
    m_mwincolour = color("MessageWindowColor", setting_color(m_mwincolour_init, {0, 0, 80, 180}));
    m_mwinframecolour = color("MessageWindowFrameColor", setting_color(m_mwinframecolour_init, {128, 0, 0, 255}));
    m_allengineframecolour = color("AllEngineFrameColor", m_mwinframecolour);
    m_blwincolour = color("MessageLogWindowColor", setting_color(m_blwincolour_init, {80, 80, 80, 180}));
    m_blwinframecolour = color("MessageLogWindowFrameColor", setting_color(m_blwinframecolour_init, {128, 128, 128, 255}));
    const auto blcurtain = color("MessageLogCurtainColor", setting_color(m_blcurtaincolour_init, {0, 0, 0, 192}));
    const auto curtain = color("CurtainColor", setting_color(m_curtaincolour_init, {0, 0, 80, 128}));
    m_blcurtaincolour = ::cw::lib::Bytes{static_cast<std::uint8_t>(std::get<0>(blcurtain)), static_cast<std::uint8_t>(std::get<1>(blcurtain)), static_cast<std::uint8_t>(std::get<2>(blcurtain)), static_cast<std::uint8_t>(std::get<3>(blcurtain))};
    m_curtaincolour = ::cw::lib::Bytes{static_cast<std::uint8_t>(std::get<0>(curtain)), static_cast<std::uint8_t>(std::get<1>(curtain)), static_cast<std::uint8_t>(std::get<2>(curtain)), static_cast<std::uint8_t>(std::get<3>(curtain))};
    const auto initial_bool = [](const ::cw::lib::Value& initial, bool fallback) {
        const auto* value = std::get_if<bool>(&initial.storage());
        return value ? *value : fallback;
    };
    m_bordering_cardname = ::cw::setting::XmlReader(*arg_data).getbool("BorderingCardName", std::nullopt, initial_bool(m_bordering_cardname_init, true));
    m_decorationfont = ::cw::setting::XmlReader(*arg_data).getbool("DecorationFont", std::nullopt, initial_bool(m_decorationfont_init, false));
    m_fontsmoothing_message = ::cw::setting::XmlReader(*arg_data).getbool("FontSmoothingMessage", std::nullopt, initial_bool(m_fontsmoothing_message_init, false));
    m_fontsmoothing_cardname = ::cw::setting::XmlReader(*arg_data).getbool("FontSmoothingCardName", std::nullopt, initial_bool(m_fontsmoothing_cardname_init, true));
    m_fontsmoothing_statusbar = ::cw::setting::XmlReader(*arg_data).getbool("FontSmoothingStatusBar", std::nullopt, initial_bool(m_fontsmoothing_statusbar_init, true));
    m_basefont["gothic"] = arg_data->gettext("FontGothic", m_basefont.at("gothic"));
    m_basefont["uigothic"] = arg_data->gettext("FontUIGothic", m_basefont.at("uigothic"));
    m_basefont["mincho"] = arg_data->gettext("FontMincho", m_basefont.at("mincho"));
    m_basefont["pmincho"] = arg_data->gettext("FontPMincho", m_basefont.at("pmincho"));
    m_basefont["pgothic"] = arg_data->gettext("FontPGothic", m_basefont.at("pgothic"));

    auto read_font = [](const std::shared_ptr<::cw::data::CWPyElement>& element,
                        auto& table, const auto& table_init) {
        if (!element) return;
        const auto key = element->get("key", "");
        const auto found = table_init.find(key);
        if (key.empty() || found == table_init.end()) return;
        const auto& defaults = found->second;
        const auto fonttype = element->get("type", "");
        const auto name = element->get_text();
        const auto pixels = element->getint(".", ::cw::lib::Value("pixels"), std::get<2>(defaults));
        const auto parse_bool = [&](const char* attr, bool fallback) {
            const auto text = element->get(attr, "");
            return text.empty() ? fallback : ::cw::util::str2bool(text);
        };
        const auto bold = parse_bool("bold", std::get<3>(defaults));
        const auto expandedbold = parse_bool("expandedbold", std::get<4>(defaults));
        const auto italic = parse_bool("italic", std::get<5>(defaults));
        // Py と同様、上書き値は空でない italic 属性の分岐だけで保存する。
        if (!element->get("italic", "").empty())
            table[key] = {fonttype, name, pixels, bold, expandedbold, italic};
    };
    if (const auto fonts = arg_data->find("Fonts"); fonts && *fonts)
        for (const auto& element : (*fonts)->m_children) read_font(element, m_fonttypes_typed, m_fonttypes_init_typed);
    if (const auto synthetic = arg_data->find("SyntheticFonts"); synthetic && *synthetic && (*synthetic)->get("key", "") == "message")
        for (const auto& element : (*synthetic)->m_children) read_font(element, m_msg_exfonts, m_msg_exfonts_init_typed);
    m_fonttypes.clear();
    for (const auto& [key, value] : m_fonttypes_typed) m_fonttypes.emplace(key, ::cw::lib::Value(std::get<0>(value)));
    const auto* initial_background_type = std::get_if<::cw::lib::Integer>(
        &m_fullscreenbackgroundtype_init.storage());
    const auto* initial_background_file = std::get_if<::cw::lib::String>(
        &m_fullscreenbackgroundfile_init.storage());
    m_fullscreenbackgroundtype = ::cw::setting::XmlReader(*arg_data).getint("FullScreenBackgroundType", std::nullopt,
        initial_background_type ? *initial_background_type : 2);
    m_fullscreenbackgroundfile = arg_data->gettext("FullScreenBackgroundFile",
        initial_background_file ? *initial_background_file : "Resource/Image/Dialog/PAD");
}

std::shared_ptr<::cw::setting::LocalSetting> LocalSetting::copy()
{
    return std::make_shared<LocalSetting>(*this);
}

namespace {
void queue_resource_error(::cw::lib::String text, ::cw::lib::String diagnostic)
{
    const auto* frame_value = ::cw::g_cwpy
        ? std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_frame.storage()) : nullptr;
    const auto frame = frame_value ? std::dynamic_pointer_cast<::cw::frame::Frame>(*frame_value) : nullptr;
    if (!frame) {
        // ネイティブのリソース確認は Frame の生成前に行われる場合がある。
        // その境界にはモーダル所有者がないため、診断情報を stderr に出す。
        std::fprintf(stderr, "%s", diagnostic.c_str());
        return;
    }
    const std::weak_ptr<::cw::frame::Frame> weak_frame = frame;
    frame->exec_func([weak_frame, text = std::move(text), diagnostic = std::move(diagnostic)](const auto&, const auto&) {
        if (const auto frame = weak_frame.lock()) {
            std::fprintf(stderr, "%s", diagnostic.c_str());
            auto dialog = std::make_shared<::cw::dialog::message::ErrorMessage>();
            dialog->initialize(nullptr, text);
            (void)::cw::dialog::show_common_modal_presentation(frame, dialog);
        }
        return ::cw::lib::Value{};
    });
}
}

void MsgDict::initialize()
{
    m__d.clear(); m__error_keys.clear();
}

void MsgDict::set_item(::cw::lib::String arg_key, ::cw::lib::String arg_msg)
{
    m__d[std::move(arg_key)] = std::move(arg_msg);
}

::cw::lib::String MsgDict::get_item(::cw::lib::String arg_key)
{
    const auto it = m__d.find(arg_key);
    if (it != m__d.end()) return it->second;
    if (m__error_keys.insert(arg_key).second)
        queue_resource_error("メッセージID[" + arg_key + "]に該当するメッセージがありません。\n"
            "デイリービルド版でこのエラーが発生した場合は、「Data/SkinBase」以下のリソースが最新版になっていない可能性があります。",
            "Message [" + arg_key + "] is not found.");
    return "*ERROR*";
}

::cw::lib::String MsgDict::get(::cw::lib::String arg_key, ::cw::lib::String arg_defvalue)
{
    const auto it = m__d.find(arg_key); return it == m__d.end() ? std::move(arg_defvalue) : it->second;
}

void RecentHistory::initialize(::cw::lib::String arg_tempdir, std::shared_ptr<::cw::data::YadoData> arg_ydata)
{
    m_tempdir = std::move(arg_tempdir);
    m_ydata_typed = std::move(arg_ydata);
    m_ydata = m_ydata_typed ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(m_ydata_typed)) : ::cw::lib::Value{};
    m_fpath = path_utf8(std::filesystem::u8path(m_tempdir) / std::filesystem::u8path("RecentHistory.xml"));
    m_scelist_typed.clear();
    m_data.reset();
    if (::cw::g_fsync && ::cw::g_fsync->is_waiting(m_fpath)) ::cw::g_fsync->sync();

    (void)user_or_native_mkdir(std::filesystem::u8path(m_tempdir));
    const auto history_status = user_or_native_stat(std::filesystem::u8path(m_fpath));
    if (history_status && history_status->is_file()) {
        m_data = ::cw::data::xml2etree(m_fpath, "", std::nullopt, std::nullopt, false);
    }
    if (!m_data) {
        m_data = std::make_shared<::cw::data::CWPyElementTree>(::cw::data::make_element("RecentHistory"), m_fpath);
        m_data->write_file(m_fpath);
    }

    std::set<::cw::lib::String> temppaths;
    if (m_data && m_data->getroot()) {
        for (const auto& element : m_data->getroot()->m_children) {
            if (!element || element->get_tag() != "Scenario") continue;
            const auto path = history_child_text(element, "WsnPath");
            const auto temppath = history_child_text(element, "TempPath");
            const auto name = history_child_text(element, "Name");
            const auto md5 = element->get("md5", "");
            if (path.empty() || temppath.empty() || md5.empty()) continue;
            const auto source_status = user_or_native_stat(std::filesystem::u8path(path));
            const auto temp_status = user_or_native_stat(std::filesystem::u8path(temppath));
            if (source_status && source_status->is_file() &&
                temp_status && temp_status->is_directory()) {
                m_scelist_typed.emplace_back(path, md5, temppath, name);
                const auto temp_path = std::filesystem::u8path(temppath);
                temppaths.insert(normalize_history_path(path_utf8(temp_path)));
            }
        }
    }
    const auto temp_root = std::filesystem::u8path(m_tempdir);
    const auto temp_root_status = user_or_native_stat(temp_root);
    if (temp_root_status && temp_root_status->is_directory()) {
        for (const auto& entry : user_or_native_list(temp_root)) {
            const auto entry_status = user_or_native_stat(entry);
            if (!entry_status || !entry_status->is_directory()) continue;
            const auto key = normalize_history_path(path_utf8(entry));
            if (temppaths.find(key) == temppaths.end())
                (void)user_or_native_remove_tree(entry);
        }
    }
    // Python版はグローバルSettingのrecenthistory_limitを読む。
    const auto limit = (::cw::g_cwpy && ::cw::g_cwpy->m_setting) ? ::cw::g_cwpy->m_setting->m_recenthistory_limit : 5;
    set_limit(limit);
    sync_recent_history_mirror(*this);
}

void RecentHistory::update_scenariopath(::cw::lib::String arg_from_normpath, ::cw::lib::String arg_to_path)
{
    std::set<::cw::lib::String> changed;
    decltype(m_scelist_typed) retained;
    for (auto record : m_scelist_typed) {
        auto& path = std::get<0>(record);
        if (normalize_history_path(path) == arg_from_normpath) {
            if (!changed.insert(arg_from_normpath).second) {
                (void)user_or_native_remove_tree(std::filesystem::u8path(std::get<2>(record)));
                continue;
            }
            path = arg_to_path;
            if (::cw::util::path_is_file(arg_from_normpath)) std::get<1>(record) = ::cw::util::get_md5(arg_from_normpath);
            else if (::cw::util::path_is_file(arg_to_path)) std::get<1>(record) = ::cw::util::get_md5(arg_to_path);
        }
        retained.push_back(std::move(record));
    }
    // Py と同様、全行の処理後にだけ、絞り込み済みの列を確定する。
    m_scelist_typed = std::move(retained);
    sync_recent_history_mirror(*this);
    write();
}

void RecentHistory::write()
{
    if (!m_data) return;
    const auto root = m_data->getroot();
    if (!root) return;
    root->clear();
    for (const auto& [path, md5, temppath, name] : m_scelist_typed) {
        auto scenario = ::cw::data::make_element("Scenario", "", std::map<::cw::lib::String, ::cw::lib::String>{{"md5", md5}});
        scenario->append(::cw::data::make_element("WsnPath", path));
        scenario->append(::cw::data::make_element("TempPath", temppath));
        if (!name.empty()) scenario->append(::cw::data::make_element("Name", name));
        root->append(scenario);
    }
    m_data->write_file(m_fpath);
}

void RecentHistory::set_limit(::cw::lib::Integer arg_value)
{
    m_limit = ::cw::lib::Value(arg_value);
    if (_remove_old(std::nullopt)) write();
}

bool RecentHistory::_remove_old(std::optional<::cw::lib::String> arg_exclude)
{
    // limit は Python の動的な値に由来する。整
    // 数・Decimal・有限の Real を、精度を失う
    // double・整数変換を経由せず保持する。 不正・ゼロ
    // 以下なら設定欠落時と同様、保持件数の整理を無効にする。
    if (!m_ydata_typed || !history_limit_enabled(m_limit)) return false;
    std::vector<RecentRecord> bookmarked;
    std::vector<RecentRecord> regular;
    for (const auto& record : m_scelist_typed) {
        if (history_path_is_bookmarked(m_ydata_typed, std::get<0>(record))) bookmarked.push_back(record);
        else regular.push_back(record);
    }
    if (!history_limit_exceeded(m_limit, regular.size())) return false;
    _sort_scelist(regular, arg_exclude);
    while (history_limit_exceeded(m_limit, regular.size())) {
        // Py と同様、変更可能な保持一覧を同じ remove() の経路へ渡す。
        remove("", false, std::ref(regular));
    }
    m_scelist_typed = std::move(regular);
    m_scelist_typed.insert(m_scelist_typed.end(), bookmarked.begin(), bookmarked.end());
    sync_recent_history_mirror(*this);
    return true;
}

void RecentHistory::_sort_scelist(std::vector<std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::String, ::cw::lib::String>>& arg_scelist, std::optional<::cw::lib::String> arg_exclude)
{
    std::set<::cw::lib::String> stamps;
    if (m_ydata_typed) stamps = m_ydata_typed->get_compstamps();
    std::stable_partition(arg_scelist.begin(), arg_scelist.end(), [&](const RecentRecord& record) {
        const auto& path = std::get<0>(record);
        const auto& name = std::get<3>(record);
        return stamps.find(name) != stamps.end() && (!arg_exclude || path != *arg_exclude);
    });
}

void RecentHistory::moveend(::cw::lib::String arg_path)
{
    std::vector<RecentRecord> moved;
    for (auto it = m_scelist_typed.begin(); it != m_scelist_typed.end();) {
        if (std::get<0>(*it) == arg_path) { moved.push_back(*it); it = m_scelist_typed.erase(it); }
        else ++it;
    }
    m_scelist_typed.insert(m_scelist_typed.end(), moved.begin(), moved.end());
    sync_recent_history_mirror(*this);
    write();
}

void RecentHistory::append(::cw::lib::String arg_name, ::cw::lib::String arg_path, ::cw::lib::String arg_temppath, std::optional<::cw::lib::String> arg_md5)
{
    // Py と同様、表記・大文字小文字・相対パスを保ち、区切りだけを変える。 正規化した識
    // 別情報を使うのは、Py が明示的に get_keypath を呼ぶ箇所だけとする。
    std::replace(arg_path.begin(), arg_path.end(), '\\', '/');
    std::replace(arg_temppath.begin(), arg_temppath.end(), '\\', '/');
    auto md5 = arg_md5 && !arg_md5->empty() ? *arg_md5 : ::cw::util::get_md5(arg_path);
    remove(arg_path, false, std::nullopt);
    m_scelist_typed.emplace_back(std::move(arg_path), std::move(md5), std::move(arg_temppath), std::move(arg_name));
    _remove_old(std::get<0>(m_scelist_typed.back()));
    sync_recent_history_mirror(*this);
    write();
}

void RecentHistory::remove(::cw::lib::String arg_path, bool arg_save, std::optional<std::reference_wrapper<std::vector<std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::String, ::cw::lib::String>>>> arg_scelist)
{
    auto path = std::move(arg_path);
    std::replace(path.begin(), path.end(), '\\', '/');
    auto* records = &m_scelist_typed;
    // Python のリストは参照なので、コピーではなく渡された一覧を変更する。
    if (arg_scelist) records = &arg_scelist->get();
    if (path.empty()) {
        // Py の scelist[0] の IndexError に相当するネイティブ境界として、黙って成功させない。
        if (records->empty()) throw std::out_of_range("RecentHistory.remove: empty list");
        {
            const auto temp = normalize_history_path(std::get<2>(records->front()));
            // Py との意図的な差異として、壊れたネイティブ履歴がキャッシュ
            // ルート自体を指す場合の保護を維持する。 古いネイティブビルド
            // では、その親をシナリオキャッシュとして保存する場合があった。
            if (!temp.empty() && temp != normalize_history_path(m_tempdir)) {
                (void)user_or_native_remove_tree(std::filesystem::u8path(temp));
            }
            records->erase(records->begin());
        }
    } else {
        for (auto it = records->begin(); it != records->end();) {
            if (std::get<0>(*it) == path) {
                const auto temp = normalize_history_path(std::get<2>(*it));
                if (!temp.empty() && temp != normalize_history_path(m_tempdir)) {
                    (void)user_or_native_remove_tree(std::filesystem::u8path(temp));
                }
                it = records->erase(it);
            } else ++it;
        }
    }
    sync_recent_history_mirror(*this);
    if (arg_save) write();
}

std::optional<::cw::lib::String> RecentHistory::check(::cw::lib::String arg_path, std::optional<::cw::lib::String> arg_md5)
{
    std::replace(arg_path.begin(), arg_path.end(), '\\', '/');
    const auto md5 = arg_md5 && !arg_md5->empty() ? *arg_md5 : ::cw::util::get_md5(arg_path);
    // Py と同様、remove() が実体の一覧を変更・保存するため、スナッ
    // プショットを走査する。 最初の有効な一致を返し、後の記録は処理しない。
    const auto records = m_scelist_typed;
    for (const auto& [path, saved_md5, temppath, name] : records) {
        const auto source_status = user_or_native_stat(std::filesystem::u8path(path));
        const auto temp_status = user_or_native_stat(std::filesystem::u8path(temppath));
        if (!source_status || !source_status->is_file() ||
            !temp_status || !temp_status->is_directory()) { remove(path, true, std::nullopt); continue; }
        if (path == arg_path && saved_md5 == md5) return temppath;
    }
    return std::nullopt;
}

void Resource::initialize(std::optional<std::shared_ptr<::cw::setting::Setting>> arg_setting)
{
    m__init = false;
    if (arg_setting && *arg_setting) init(*arg_setting);
}

bool Resource::to_bool()
{
    return m__init;
}

void Resource::init(std::shared_ptr<::cw::setting::Setting> arg_setting)
{
    if (!arg_setting) { m__init = false; return; }
    m__init = true;
    m_setting = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(arg_setting));
    m_skindir = arg_setting->m_skindir;
    m_ext_img = ::cw::g_M_IMG; m_ext_bgm = ::cw::g_M_MSC; m_ext_snd = ::cw::g_M_SND;
#if defined(_DEBUG)
#endif
    const auto fontpaths = get_fontpaths();
#if defined(_DEBUG)
#endif
    m_fontpaths_typed = fontpaths;
    // Value はマップを再帰的に含められないため、安定した印を
    // 保持し、 完全な辞書は型付きの対応フィールドから公開する。
    m_fontpaths = ::cw::lib::Value("typed-font-paths");
    std::map<::cw::lib::String, ::cw::lib::String> installed_font_names;
    std::set<::cw::lib::String> known_faces;
    for (const auto& value : m_facenames) {
        if (const auto face = resource_key(value); !face.empty()) known_faces.insert(face);
    }
    install_defaultfonts(fontpaths, std::move(known_faces), installed_font_names);
#if defined(_DEBUG)
#endif
    const auto [fontnames, fontnames_init] = set_systemfonttable();
#if defined(_DEBUG)
#endif
    m_fontnames_typed = fontnames;
    m_fontnames_init_typed = fontnames_init;
    init_sounds();
#if defined(_DEBUG)
#endif
    m_msgs = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(get_msgs(arg_setting)));
#if defined(_DEBUG)
#endif

    // ResourceTableを型付きで作成する。画像/音声の実体はSDLスレッドで
    // 遅延ロードする設計とし、ここでは空表でもキー解決可能にしておく。
    auto make_table = [](const ::cw::lib::String& name) {
        auto table = std::make_shared<::cw::setting::ResourceTable>();
        table->initialize(name, std::nullopt, std::nullopt, std::nullopt);
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
    };
    m_buttons = get_buttons(); m_dialogs = get_dialogs({}, {}, true);
    init_debugresources();
    m_pygamedialogs = get_dialogs({}, {}, false); m_cursors = get_cursors();
    m_stones = get_stones(); m_wxstones = get_wxstones(); m_statuses = get_statuses({}, false);
    m_cardbgs = get_cardbgs({}, {}); m_wxcardbgs = m_cardbgs;
    m_cardnamecolorhints = get_cardnamecolorhints(m_cardbgs);
    m_specialchars_is_changed = false; m_specialchars = get_specialchars();
#if defined(_DEBUG)
#endif
    if (m_buttons.is_none()) m_buttons = make_table("Button");
    if (m_dialogs.is_none()) m_dialogs = make_table("Dialog");
    if (m_debugs.is_none()) m_debugs = make_table("Debug");
    if (m_cursors.is_none()) m_cursors = make_table("Cursor");
    if (m_stones.is_none()) m_stones = make_table("Stone");
    if (m_statuses.is_none()) m_statuses = make_table("Status");
    if (m_cardbgs.is_none()) m_cardbgs = make_table("CardBg");
    const auto [fonts, exfonts] = create_fonts();
#if defined(_DEBUG)
#endif
    m_fonts = fonts; m_msg_exfonts = exfonts;
    s_ext_img = m_ext_img; s_buttons = m_buttons; s_dialogs = m_dialogs; s_debugs = m_debugs; s_pygamedialogs = m_pygamedialogs; s_pygamedebugs = m_pygamedebugs;
    s_cursors = m_cursors; s_stones = m_stones; s_wxstones = m_wxstones; s_statuses = m_statuses; s_cardbgs = m_cardbgs; s_wxcardbgs = m_wxcardbgs; s_cardnamecolorhints = m_cardnamecolorhints; s_specialchars = m_specialchars; s_fonts = m_fonts; s_msg_exfonts = m_msg_exfonts;
    s_specialchars_is_changed = false;
    init_wxresources();
#if defined(_DEBUG)
#endif

    m_ignorecase_table.clear();
    std::error_code ec;
    for (const auto& relative : {"Table", "Bgm", "Sound", "BgmAndSound", "Resource/Image"}) {
        const auto root = std::filesystem::u8path(m_skindir) / relative;
        if (!std::filesystem::is_directory(root, ec)) continue;
        for (std::filesystem::recursive_directory_iterator it(root, ec), end; it != end && !ec; it.increment(ec)) {
            if (!it->is_regular_file(ec)) continue;
            const auto actual = path_utf8(it->path());
            const auto lower = ::cw::lib::encoding::lower(actual);
            m_ignorecase_table[lower] = actual;
        }
    }
#if defined(_DEBUG)
#endif
}

static std::optional<std::filesystem::path> mounted_ignorecase_path(
    const std::filesystem::path& requested)
{
    auto resolved = ::cardwirth::platform::resolve_mounted_user_path(requested);
    if (!resolved) return std::nullopt;
    auto root = *resolved;
    while (root.has_parent_path() && root.parent_path() != root &&
           ::cardwirth::platform::is_mounted_user_path(root.parent_path()))
        root = root.parent_path();
    auto current = root;
    const auto relative = resolved->lexically_relative(root);
    std::vector<std::filesystem::path> components;
    for (const auto& component : relative) components.push_back(component);
    for (std::size_t index = 0; index < components.size(); ++index) {
        const auto& component = components[index];
        const auto wanted_text = path_utf8(component);
        const auto wanted_lower = ::cw::lib::encoding::lower(wanted_text);
        const auto entries = ::cardwirth::platform::list_mounted_user_path(current, true);
        if (!entries) return std::nullopt;
        const ::cardwirth::platform::StorageEntry* folded = nullptr;
        const ::cardwirth::platform::StorageEntry* exact = nullptr;
        for (const auto& entry : *entries) {
            const auto actual = entry.name.empty() ? path_utf8(entry.path.filename()) : entry.name;
            if (actual == wanted_text) { exact = &entry; break; }
            if (!folded && ::cw::lib::encoding::lower(actual) == wanted_lower) folded = &entry;
        }
        const auto* selected = exact ? exact : folded;
        if (!selected) return std::nullopt;
        const bool final_component = index + 1 == components.size();
        if (final_component ? !selected->stat.is_file() : !selected->stat.is_directory())
            return std::nullopt;
        // 確認済みのディレクトリー項目名から再構築する。 マウントアダ
        // プターによっては大文字小文字を無視して検索した後も entry.path
        // に要求時の表記を残すため、 Python の名前対応
        // 表と同じく、実際にストレージへ保存された表記を使う。
        const auto actual = selected->name.empty()
            ? selected->path.filename()
            : ::cw::lib::encoding::path_from_utf8(selected->name);
        current /= actual;
    }
    const auto status = ::cardwirth::platform::stat_mounted_user_path(current, true);
    if (!status || !status->is_file()) return std::nullopt;
    // Storage の走査は内部でマウントルートの絶対パスを使うが、 Python
    // ・リソースの境界では呼び出し側の論理パス形式を維持する。
    return requested.is_absolute()
        ? std::optional<std::filesystem::path>(current)
        : std::optional<std::filesystem::path>(current.lexically_relative(root));
}

::cw::lib::String Resource::get_filepath(::cw::lib::String arg_fpath)
{
    if (::cw::g_fsync && ::cw::g_fsync->is_waiting(arg_fpath)) ::cw::g_fsync->sync();
    if (arg_fpath.empty() || ::cw::binary::image::path_is_code(arg_fpath)) return arg_fpath;
    const auto mounted_path = std::filesystem::u8path(arg_fpath);
    if (::cardwirth::platform::is_mounted_user_path(mounted_path)) {
        if (const auto actual = mounted_ignorecase_path(mounted_path)) return path_utf8(*actual);
        return arg_fpath;
    }
    if (::cw::util::path_is_file(arg_fpath)) return arg_fpath;
    const auto lower = ::cw::lib::encoding::lower(arg_fpath);
    const auto it = m_ignorecase_table.find(lower);
    if (it != m_ignorecase_table.end()) {
        if (const auto* text = std::get_if<::cw::lib::String>(&it->second.storage())) return *text;
    }
    if (::cw::g_cwpy) {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_sdata.storage());
        const auto data = object && *object ? std::dynamic_pointer_cast<::cw::data::SystemData>(*object) : nullptr;
        if (data) {
            const auto found = data->m_ignorecase_table.find(lower);
            if (found != data->m_ignorecase_table.end()) return found->second;
        }
    }
    return arg_fpath;
}

void Resource::dispose()
{
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_fonts.storage()); object && *object) {
        if (const auto table = std::dynamic_pointer_cast<::cw::setting::ResourceTable>(*object)) {
            for (const auto& key : table->iterkeys()) {
                // Python版は、実際に生成済みのFontだけを破棄する。
                // 未ロード項目をここでget_item()すると、スキン切替中に新規Fontを
                // 生成してしまい、宿ロードそのものを失敗させる。
                if (!table->is_loaded(key)) continue;
#if defined(_WIN32)
                ::cw::lib::Value value;
                try {
                    value = table->get_item(key);
                } catch (const std::runtime_error&) {
                    // 遅延フォントの読み込みに失敗しても読み込み済みとして数えるが、破棄すべ
                    // き Font はない。 失敗後も後処理・再読み込みができるようにする。
                    continue;
                }
#else
                const auto value = table->get_item(key);
#endif
                if (const auto* child = std::get_if<::cw::lib::ObjectPtr>(&value.storage()); child && *child) {
                    if (const auto font = std::dynamic_pointer_cast<::cw::imageretouch::Font>(*child)) font->dispose();
                }
            }
        }
    }
    clear_systemfonttable();
    clear_native_cursors();
    m__statusbtnbmp0.clear(); m__statusbtnbmp1.clear(); m__statusbtnbmp2.clear();
    m__init = false;
}

::cw::lib::Integer Resource::get_cardnamecolorborder()
{
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_setting.storage()); object && *object) {
        if (const auto setting = std::dynamic_pointer_cast<::cw::setting::Setting>(*object)) return setting->get_bordering_cardname() ? 92 : 116;
    }
    return 116;
}

