void Resource::init_wxresources()
{
    // wx の Bitmap/Cursor は SDL 互換オブジェクトで置き換える。
    // 実画像のデコードとマスク・色深度・論理倍率の情報は、各リソースローダーで保持する。
    m_buttons = get_buttons(); m_dialogs = get_dialogs({}, {}, true);
    init_debugresources(false);
    m_cursors = get_cursors(); m_wxstones = get_wxstones(); m_wxstatuses = get_statuses({}, true); m_wxcardbgs = get_cardbgs({}, {}, true);
}

void Resource::init_debugresources(bool arg_game_images)
{
    const auto identity = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
        return args.at(0);
    };
    const auto dpi_scale = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
        return ::cw::ppis(args.at(0));
    };
    const auto window_scale = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
        return ::cw::wins(args.at(0));
    };
    const auto dpi_bitmap = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
        auto image = ::cw::util::load_wxbmp(callback_path(args), callback_bool(kwargs, "mask", true), {}, {},
            std::nullopt, true, callback_bool(kwargs, "can_loaded_scaledimage", true), false,
            ::cw::lib::Value(::cw::g_dpi_level));
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
    };
    if (arg_game_images) {
        const auto image_loader = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
            auto image = ::cw::util::load_image(callback_path(args), callback_bool(kwargs, "mask", true),
                {0, 0}, std::nullopt, true, false, callback_bool(kwargs, "can_loaded_scaledimage", true),
                false, callback_integer(kwargs, "up_scr") ? std::optional<::cw::lib::Value>(
                    ::cw::lib::Value(*callback_integer(kwargs, "up_scr"))) : std::nullopt, false);
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
        };
        m_pygamedebugs = get_debugs(image_loader, {}, [](const auto& args, const auto&) {
            return ::cw::s(args.at(0));
        }, true);
    }
    m_debugs = get_debugs(dpi_bitmap, {}, dpi_scale, true);
    m_debugs_wx = get_debugs({}, {}, window_scale, true);
    m_debugs_noscale = get_debugs({}, {}, identity, false);
}

void Resource::init_debugicon()
{
    const auto native = ::cw::setting::backend();
    const auto reload = [this, native] {
        if (native && native->reload_debug_images) native->reload_debug_images(*this);
        else init_debugresources();
    };
    if (native && native->dispatch_ui) native->dispatch_ui(reload);
    else reload();
    if (native && native->pump_ui) native->pump_ui();
}

std::map<::cw::lib::String, ::cw::lib::String> Resource::get_fontpaths()
{
    const auto skinfont = std::filesystem::u8path(m_skindir) / "Resource/Font";
    const auto userfont = std::filesystem::u8path("System/Font");
    const auto fallback = std::filesystem::u8path("Data/Font");
    const std::array<std::pair<const char*, const char*>, 5> files{{
        {"gothic.ttf", "ＭＳ ゴシック"}, {"uigothic.ttf", "MS UI Gothic"},
        {"mincho.ttf", "ＭＳ 明朝"}, {"pgothic.ttf", "ＭＳ Ｐゴシック"}, {"pmincho.ttf", "ＭＳ Ｐ明朝"}}};
    std::map<::cw::lib::String, ::cw::lib::String> result;
    s_facenames_init.clear(); s_facenames_lower.clear(); m_facenames.clear(); m_facenames_lower.clear();
    const auto lower_face = [](const ::cw::lib::String& value) {
        return ::cw::lib::encoding::python_lower(value);
    };
    const auto native_paths = backend()->enumerate_fonts
        ? backend()->enumerate_fonts(path_utf8(skinfont), {"ＭＳ ゴシック", "MS UI Gothic", "ＭＳ 明朝", "ＭＳ Ｐゴシック", "ＭＳ Ｐ明朝"})
        : std::map<::cw::lib::String, ::cw::lib::String>{};
#if defined(_WIN32)
    // .ttc ファイルから書体を特定できたかとは独立して、実際に列挙した書体
    // 一覧を保持する。 msgothic.ttc のような一つのコレクションに
    // は複数の MS 書体が含まれるため、ファイル名だけの照合では不足する。
    for (const auto& face : enumerate_windows_font_faces()) {
        const auto lowered = lower_face(face);
        s_facenames_init[face] = face;
        s_facenames_lower.insert(lowered);
        m_facenames.emplace_back(face);
        m_facenames_lower.emplace_back(lowered);
    }
#endif
    std::map<::cw::lib::String, ::cw::lib::String> scanned;
    for (const auto& [name, path] : native_paths) scanned[lower_face(name)] = path;
    for (const auto& [file, alternate] : files) {
        const auto skinpath = skinfont / file; const auto fallbackpath = fallback / file;
        const auto userpath = userfont / file;
        std::filesystem::path path;
        if (std::filesystem::is_regular_file(skinpath)) path = skinpath;
        else if (std::filesystem::is_regular_file(userpath)) path = userpath;
        else if (std::filesystem::is_regular_file(fallbackpath)) path = fallbackpath;
        // Py はインストール済みの代替書体があれば、フォントファイルを解
        // 析せず使う。 ネイティブの同梱・システムファイル探索より先にその
        // 書体を優先する。 ファイル名の照合では別書体や TTC を選ぶ場
        // 合があり、共通の単一 SFNT 名パーサーへ渡してはならない。
        else if (s_facenames_init.contains(alternate)) continue;
        // Web/Linux では、bundled_font_root() の同梱 IPA ファイルを使う。
        else if (const auto bundled = bundled_logical_font(path_utf8(std::filesystem::u8path(file).stem()));
                 !bundled.empty()) path = bundled;
        else if (const auto found = find_font_file(scanned, path_utf8(std::filesystem::u8path(file).stem()), alternate); !found.empty()) path = std::filesystem::u8path(found);
        else {
            // Py と同様、対応ファイルがなくてもインストール済みの代替書体は使える
            // 。 ファイルもその書体もなければ NoFontError を通知する。
            if (s_facenames_init.contains(alternate)) continue;
            throw ::cw::setting::NoFontError(::cw::lib::String(file) + " not found.");
        }
        const auto key = path_utf8(std::filesystem::u8path(file).stem()); result[key] = path_utf8(path);
        // 見つかったファイルは、同梱 IPA や複数書体を持つ TTC
        // の場合がある。 それだけで Windows の代替書体
        // が存在すると判断せず、上の実際の書体列挙を正本とする。
    }
    for (const auto& [name, path] : native_paths) {
        const auto face = path_utf8(std::filesystem::u8path(path).stem());
        const bool known = std::any_of(m_facenames.begin(), m_facenames.end(), [&face](const auto& value) {
            return resource_key(value) == face;
        });
        if (!face.empty() && !known) {
            m_facenames.emplace_back(face);
            m_facenames_lower.emplace_back(lower_face(face));
            // 共通ホストは Win32 GDI の登録表ではなく、利用可能な
            // ファイルを列挙する。 その実在するファイル由来の名前を同じ設定
            // モデルへ公開し、Linux/macOS の選択欄を空にしない。
            s_facenames_init.emplace(face, face);
            s_facenames_lower.insert(lower_face(face));
        }
        (void)name;
    }
    return result;
}

std::map<::cw::lib::String, ::cw::lib::String> Resource::get_fontpaths_s(::cw::lib::String arg_fontdir, std::set<::cw::lib::String> arg_facenames)
{
    std::map<::cw::lib::String, ::cw::lib::String> result;
    const std::array<const char*, 5> files{{"gothic.ttf", "uigothic.ttf", "mincho.ttf", "pgothic.ttf", "pmincho.ttf"}};
    for (const auto* file : files) {
        const auto path = std::filesystem::u8path(arg_fontdir) / file;
        if (std::filesystem::is_regular_file(path)) {
            result[path_utf8(std::filesystem::u8path(file).stem())] = path_utf8(path);
        } else {
            const auto stem = path_utf8(std::filesystem::u8path(file).stem());
            const std::array<const char*, 5> alternates{{"ＭＳ ゴシック", "MS UI Gothic", "ＭＳ 明朝", "ＭＳ Ｐゴシック", "ＭＳ Ｐ明朝"}};
            const auto index = static_cast<std::size_t>(std::distance(std::begin(files), std::find(std::begin(files), std::end(files), file)));
            if (index >= alternates.size() || !arg_facenames.contains(alternates[index]))
                // リソース初期化のハンドラーは、この型そのものを捕捉する。
                throw ::cw::setting::NoFontError(::cw::lib::String(file) + " not found.");
            (void)stem;
        }
    }
    return result;
}

void Resource::install_defaultfonts(std::map<::cw::lib::String, ::cw::lib::String> arg_fontpaths, std::set<::cw::lib::String> arg_facenames, std::map<::cw::lib::String, ::cw::lib::String>& arg_d)
{
    bool registered = false;
    for (const auto& [name, path] : arg_fontpaths) {
        const auto face = ::cw::util::get_truetypefontname(path);
        const std::map<::cw::lib::String, ::cw::lib::String> aliases{
            {"IPAUIGothic", "IPA UIゴシック"}, {"IPAGothic", "IPAゴシック"},
            {"IPAPGothic", "IPA Pゴシック"}, {"IPAMincho", "IPA明朝"},
            {"IPAPMincho", "IPA P明朝"}};
        const auto alias = aliases.find(face);
        if (arg_facenames.contains(face) ||
            (alias != aliases.end() && arg_facenames.contains(alias->second))) {
            arg_d[name] = face;
            continue;
        }
        // Py は Windows のワーカーで登録する。ネイティブ版では全 OS
        // でこの共通バックエンド境界を使う。 Py と同様、登録結果とは独立
        // して実際の TTF の書体名を公開し、ファイル名本体で代用しない。
        if (backend()->install_font) registered = backend()->install_font(path) || registered;
        if (face.empty()) throw std::invalid_argument("Failed to get facename from " + name);
        arg_d[name] = face;
    }
    s_fontnames_init = arg_d;
    if (registered && backend()->notify_font_change) backend()->notify_font_change();
}

std::tuple<std::map<::cw::lib::String, ::cw::lib::String>, std::map<::cw::lib::String, ::cw::lib::String>> Resource::set_systemfonttable()
{
    std::map<::cw::lib::String, ::cw::lib::String> names{
        {"gothic", "IPAゴシック"}, {"uigothic", "IPA UIゴシック"}, {"mincho", "IPA明朝"},
        {"pgothic", "IPA Pゴシック"}, {"pmincho", "IPA P明朝"}};
    for (auto& [key, value] : names) {
        const auto bundled = m_fontpaths_typed.find(key);
        if (bundled != m_fontpaths_typed.end() && !bundled->second.empty()) value = bundled->second;
    }
    // Python の初期表は同梱 IPA フォントを表す。
    // Windows の MS 書体は検出したローカルの上書
    // きであり、後で書体が使えなくなった時の代替値ではない。
    const auto initial = names;
#if defined(_WIN32)
    // CardWirthPy と同様、FontEnumerator が報告した Windows
    // 書体だけを選ぶ。 Windows フォントがない・削除されている場合は同梱 IPA
    // を維持し、CreateFontW が無関係な書体を黙って選ばないようにする。
    const auto installed = enumerate_windows_font_faces();
    const auto select_if_installed = [&installed, &names](const char* key, const char* face) {
        if (installed.contains(face)) names[key] = face;
    };
    select_if_installed("gothic", "ＭＳ ゴシック");
    select_if_installed("uigothic", "MS UI Gothic");
    select_if_installed("mincho", "ＭＳ 明朝");
    select_if_installed("pgothic", "ＭＳ Ｐゴシック");
    select_if_installed("pmincho", "ＭＳ Ｐ明朝");
#endif
    std::shared_ptr<::cw::setting::Setting> setting;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_setting.storage()); object && *object) setting = std::dynamic_pointer_cast<::cw::setting::Setting>(*object);
    if (setting) {
        const auto basefonts = setting->get_basefont();
        for (auto& [key, value] : names) {
            const auto base = basefonts.find(key);
            if (base != basefonts.end() && !base->second.empty()) value = base->second;
        }
    }
    s_fontnames_init = initial;
    m_fontnames = ::cw::lib::Value("system-font-table"); m_fontnames_init = ::cw::lib::Value("system-font-table");
    return {names, initial};
}

void Resource::clear_systemfonttable()
{
    std::set<::cw::lib::String> installed;
    {
        std::scoped_lock lock(g_setting_font_mutex);
        installed = g_setting_installed_fonts;
    }
    for (const auto& path : installed) if (backend()->remove_font) backend()->remove_font(path);
    if (!installed.empty() && backend()->notify_font_change) backend()->notify_font_change();
}

ResolvedFontRequest Resource::get_fontfromtype(::cw::lib::String arg_name, std::optional<FontRequestValue> arg_fontinfo)
{
    std::shared_ptr<::cw::setting::Setting> setting;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_setting.storage()); object && *object)
        setting = std::dynamic_pointer_cast<::cw::setting::Setting>(*object);
    if (!setting) throw std::logic_error("font lookup requires a live Setting");
    if (!arg_fontinfo && setting) {
        const auto types = setting->get_fonttypes();
        if (const auto it = types.find(arg_name); it != types.end()) arg_fontinfo = it->second;
    }
    auto [basename, fontname, pixels, bold, bold_upscr, italic] = arg_fontinfo.value_or(
        FontSettingValue{arg_name, "", -1, false, false, false});
    if (!basename.empty()) {
        // Python と同様、抽象ファミリーは現在の表で解決し、同梱の代
        // 替既定値だけを記録する fontnames_init は使わない
        // 。 明示的な書体を使うのは、抽象ファミリーが空の場合だけとする。
        fontname.clear();
        const auto base = setting->get_basefont();
        // Py の basefont[basename] と同様、未知のファミリーはエラ
        // ーにする。 既知のファミリーで値が空なら、fontnames の代替を使える。
        const auto it = base.find(basename);
        if (it == base.end()) throw std::out_of_range("Unknown base font: " + basename);
        fontname = it->second;
        if (fontname.empty()) {
            if (const auto it = m_fontnames_typed.find(basename); it != m_fontnames_typed.end())
                fontname = it->second;
        }
    }
    return {fontname, pixels, bold, bold_upscr, italic};
}

std::shared_ptr<::cw::lib::Window> Resource::get_wxfont(::cw::lib::String arg_name, std::optional<::cw::lib::Integer> arg_size, std::optional<::cw::lib::Integer> arg_pixelsize, ::cw::lib::Integer arg_family, ::cw::lib::Integer arg_style, ::cw::lib::Integer arg_weight, ::cw::lib::Integer arg_encoding, bool arg_adjustsize, bool arg_adjustsizewx3, std::optional<::cw::lib::Integer> arg_pointsize)
{
    auto result = std::make_shared<::cw::lib::Window>();
    auto [face, pixels, bold, bold_upscr, italic] = get_fontfromtype(arg_name, std::nullopt);
    (void)arg_family; (void)arg_style; (void)arg_weight; (void)arg_encoding;
    if (!arg_pixelsize && !arg_size)
        arg_pixelsize = std::get<::cw::lib::Integer>(::cw::wins(::cw::lib::Value(::cw::lib::Integer{14})).storage());
    ::cw::lib::Integer psize;
    if (arg_pointsize) psize = *arg_pointsize;
    else if (arg_pixelsize && *arg_pixelsize != 0) {
        psize = *arg_pixelsize;
        if (arg_adjustsizewx3) --psize;
    } else {
        if (!arg_size) throw std::logic_error("get_wxfont: zero pixel size requires size");
        // Py と同様、int(96/72 * size + 0.5) を使い、負のサイズで
        // もゼロ方向へ切り捨てる。 数値ゼロの pixelsize は size に戻す。
        const auto converted = (1.0 / 72.0 * 96.0) * static_cast<double>(*arg_size) + 0.5;
        // Python の整数は任意精度なので、ネイティブの Integer
        // の範囲外の要求は変換前に拒否し、未定義動作を避ける。
        const auto lower = static_cast<double>((std::numeric_limits<::cw::lib::Integer>::min)());
        if (!std::isfinite(converted) || converted < lower || converted >= -lower)
            throw std::overflow_error("get_wxfont: size exceeds Integer range");
        psize = static_cast<::cw::lib::Integer>(converted);
    }
    if (!arg_pointsize && (arg_name == "tree" || arg_name == "slider" || arg_adjustsize) && psize > 15 && (psize % 2) != 0) ++psize;
    // ネイティブ表現の境界として、Window は wx.Font ではな
    // く論理的な要求を持つ。 ここではゼロ・符号付きの要求を維持し、描画時
    // の最小確保寸法やプラットフォーム単位は共通フォント処理で管理する。
    result->title = face; result->bounds.width = psize; result->bounds.height = psize;
    if (backend()->create_font) {
        const bool make_bold = (::cw::g_UP_SCR > 1.0 ? bold_upscr : bold).value_or(false);
        const bool make_italic = italic.value_or(false);
        (void)backend()->create_font(face, psize, make_bold, make_italic);
    }
    return result;
}

std::shared_ptr<::cw::imageretouch::Font> Resource::create_font(::cw::lib::String arg_ftype, ::cw::lib::String arg_basetype, ::cw::lib::String arg_fontname, ::cw::lib::Integer arg_size_noscale, bool arg_defbold, bool arg_defbold_upscr, bool arg_defitalic, ::cw::lib::Integer arg_pixelsadd, bool arg_nobold, std::optional<FontRequestValue> arg_fontinfo)
{
    const auto [fontname0, pixels0, bold0, bold_upscr, italic0] = get_fontfromtype(arg_ftype, arg_fontinfo);
    auto fontname = fontname0;
    auto pixels = pixels0 <= 0 ? arg_size_noscale : pixels0;
    pixels += arg_pixelsadd;
    // 拡大時の太字形式を選ぶ前に、Py と同じ None の既定値を適用する。
    bool bold = ::cw::g_UP_SCR > 1.0 ? bold_upscr.value_or(arg_defbold_upscr)
                                   : bold0.value_or(arg_defbold);
    const bool italic = italic0.value_or(arg_defitalic);
    if (arg_nobold) bold = false;
    // Py と同じ符号付き Font 要求である -cw.s(pixels_noscale)
    // を維持する。 確保の最小値は共通の描画境界で管理し、ここで要求を変更
    // してゼロ以下の設定のポイント寸法・既定寸法の意味を失わないようにする。
    const auto scaled_pixels = std::get<::cw::lib::Integer>(::cw::s(::cw::lib::Value(pixels)).storage());
    if (scaled_pixels == (std::numeric_limits<::cw::lib::Integer>::min)())
        throw std::overflow_error("font size cannot be negated within Integer range");
    const auto native_backend = backend();
    std::shared_ptr<::cw::imageretouch::Font> result;
    if (native_backend->create_font) result = native_backend->create_font(fontname, -scaled_pixels, bold, italic);
    if (!result) {
        result = std::make_shared<::cw::imageretouch::Font>();
        result->initialize(fontname, -scaled_pixels, bold, italic);
    }
    // Python の create_font と同様、生成時に拡縮して -cw.s(pixels_noscale) を渡す。
    (void)arg_basetype; (void)arg_fontname;
    return result;
}

std::shared_ptr<::cw::imageretouch::Font> Resource::create_exfont(::cw::lib::String arg_ftype, std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool> arg_fontinfo, std::map<::cw::lib::String, std::shared_ptr<::cw::imageretouch::Font>> arg_basetable, bool arg_nobold)
{
    if (std::get<0>(arg_fontinfo) == "inherit") {
        const auto it = arg_basetable.find(arg_ftype);
        if (it != arg_basetable.end() && it->second) return it->second;
        // 継承を表す特別な値を、インストール済みのフォント名として解決しない。
        throw std::runtime_error("Inherited font has no base: " + arg_ftype);
    }
    return create_font(arg_ftype, std::get<0>(arg_fontinfo), std::get<1>(arg_fontinfo), std::get<2>(arg_fontinfo), std::get<3>(arg_fontinfo), std::get<4>(arg_fontinfo), std::get<5>(arg_fontinfo), 0, arg_nobold, arg_fontinfo);
}

#if defined(_WIN32)
std::shared_ptr<::cw::imageretouch::Font> Resource::find_message_font(
    const ::cw::lib::String& category)
{
    const auto lookup = [](const ::cw::lib::Value& source, const ::cw::lib::String& key)
        -> std::shared_ptr<::cw::imageretouch::Font> {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&source.storage());
        if (!object || !*object) return {};
        const auto table = std::dynamic_pointer_cast<ResourceTable>(*object);
        if (!table) return {};
        try {
            const auto value = table->get(::cw::lib::Value(key), std::nullopt);
            if (!value) return {};
            const auto* font = std::get_if<::cw::lib::ObjectPtr>(&value->storage());
            return font && *font ? std::dynamic_pointer_cast<::cw::imageretouch::Font>(*font)
                                 : nullptr;
        } catch (const std::runtime_error&) {
            // LazyResource は読み込み失敗を記録済みである。 文
            // 字描画やバックログ再生成へ、そのリソースエラーを伝播させない。
            return {};
        }
    };
    if (category != "message")
        if (auto font = lookup(m_msg_exfonts, category)) return font;
    return lookup(m_fonts, "message");
}
#endif

std::tuple<::cw::lib::Value, ::cw::lib::Value> Resource::create_fonts()
{
    auto fonts = std::make_shared<::cw::setting::ResourceTable>(); fonts->initialize("Font", std::nullopt, std::nullopt, std::nullopt);
    auto exfonts = std::make_shared<::cw::setting::ResourceTable>(); exfonts->initialize("SyntheticFontsForMessage", std::nullopt, std::nullopt, std::nullopt);
    std::shared_ptr<::cw::setting::Setting> setting;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_setting.storage()); object && *object) setting = std::dynamic_pointer_cast<::cw::setting::Setting>(*object);
    if (!setting) return {::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(fonts)), ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(exfonts))};
    const auto types = setting->get_fonttypes();
    const auto add_font = [&](const ::cw::lib::String& key, const ::cw::lib::String& type, bool nobold, ::cw::lib::Integer add = 0) {
        const auto it = types.find(type); if (it == types.end()) return;
        const auto info = it->second;
        auto callback = [this, type, info, nobold, add](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(create_font(type, std::get<0>(info), std::get<1>(info), std::get<2>(info), std::get<3>(info), std::get<4>(info), std::get<5>(info), add, nobold, info))); };
        fonts->set(key, std::move(callback), {}, {});
    };
    const auto add_fixed_font = [&](const ::cw::lib::String& key, const ::cw::lib::String& type,
                                    ::cw::lib::Integer default_pixels, bool nobold) {
        const auto it = types.find(type); if (it == types.end()) return;
        const auto info = it->second;
        auto callback = [this, type, info, default_pixels, nobold](
                            const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(
                create_font(type, std::get<0>(info), std::get<1>(info), default_pixels,
                            std::get<3>(info), std::get<4>(info), std::get<5>(info),
                            0, nobold, info)));
        };
        fonts->set(key, std::move(callback), {}, {});
    };
    add_font("card_uselimit", "uselimit", false); add_font("mcard_name", "cardname", false); add_font("pcard_name", "ccardname", false);
    add_font("pcard_level", "level", false); add_font("message", "message", true); add_font("selectionbar", "selectionbar", false);
    // Python の create_fonts() と同様、三つの Bill
    // 用フォントに明示的な代替サイズを渡す。 フォント種別の既定値 -1
    // を渡すと、メッセージログの張り紙ですべて一ピクセルになってしまう。
    add_fixed_font("scenario", "scenario", 20, false);
    add_fixed_font("scenariodesc", "dlglist", 13, false);
    add_fixed_font("targetlevel", "targetlevel", 15, false);
    add_font("backlog_page", "logpage", false); add_font("price", "price", false); add_font("numcards", "numcards", false);
    if (const auto it = types.find("numcards"); it != types.end()) {
        const auto pixels = std::get<2>(it->second);
        // Py の min(0, -min(pixels // 2, pixels - 16)) に合わせ
        // る。 pixels が 16 以下なら結果はゼロであり、この形で符号付き減算の桁あふれも避ける。
        const auto personal_add = pixels <= 16 ? 0 : -std::min(pixels / 2, pixels - 16);
        add_font("numcards_personal", "numcards", false, personal_add);
    }
    add_font("sbarpanel", "sbarpanel", false);
    add_font("sbarprogress", "sbarprogress", false); add_font("sbarbtn", "sbarbtn", false); add_font("sbardesc", "sbardesc", false); add_font("sbardesctitle", "sbardesctitle", false); add_font("statusimg1", "statusnum", false); add_font("statusimg2", "statusnum", false, -2); add_font("statusimg3", "statusnum", false, -4); add_font("screenshot", "screenshot", false);
    const auto extypes = setting->get_msg_exfonts();
    for (const auto& [key, info] : extypes) {
        // Py と同様、全プラットフォームで実際の遅延メッセージリソースの寸
        // 法・装飾を継承し、新しい複製は作らない。 これらのコールバックは
        // create_fonts() より長く残るため、表は値で保持する。
        auto callback = [this, fonts, info](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
            if (std::get<0>(info) == "inherit") {
                const auto value = fonts->get_item(::cw::lib::Value("message"));
                const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
                if (!object || !*object ||
                    !std::dynamic_pointer_cast<::cw::imageretouch::Font>(*object))
                    throw std::runtime_error("Inherited message font is unavailable");
                return value;
            }
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(
                create_exfont("message", info, {}, true)));
        };
        exfonts->set(key, std::move(callback), {}, {});
    }
    return {::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(fonts)), ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(exfonts))};
}

::cw::lib::Value Resource::create_wxbutton(std::shared_ptr<::cw::lib::Panel> arg_parent, ::cw::lib::Integer arg_cid, std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_size, std::optional<::cw::lib::String> arg_name, std::optional<std::shared_ptr<::cw::lib::Bitmap>> arg_bmp, bool arg_chain)
{
    if (backend()->create_button) return backend()->create_button(std::move(arg_parent), arg_cid, arg_size, std::move(arg_name), std::move(arg_bmp), arg_chain);
    if (arg_bmp && *arg_bmp) return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*arg_bmp));
    auto button = std::make_shared<::cw::lib::Control>(); button->id = arg_cid; button->title = arg_name.value_or(""); button->bounds.width = std::get<0>(arg_size); button->bounds.height = std::get<1>(arg_size);
    button->visible = true;
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(button));
}

::cw::lib::Value Resource::create_wxbutton_dbg(std::shared_ptr<::cw::lib::Panel> arg_parent, ::cw::lib::Integer arg_cid, std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_size, std::optional<::cw::lib::String> arg_name, std::optional<std::shared_ptr<::cw::lib::Bitmap>> arg_bmp)
{
    if (backend()->create_button) return backend()->create_button(std::move(arg_parent), arg_cid, arg_size, std::move(arg_name), std::move(arg_bmp), false);
    if (arg_bmp && *arg_bmp) return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*arg_bmp));
    auto button = std::make_shared<::cw::lib::Control>(); button->id = arg_cid; button->title = arg_name.value_or(""); button->bounds.width = std::get<0>(arg_size); button->bounds.height = std::get<1>(arg_size);
    button->visible = true;
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(button));
}

std::tuple<std::shared_ptr<::cw::lib::Surface>, std::shared_ptr<::cw::lib::Surface>, std::shared_ptr<::cw::lib::Surface>, std::shared_ptr<::cw::lib::Surface>> Resource::create_cornerimg(std::tuple<::cw::lib::Integer, ::cw::lib::Integer, ::cw::lib::Integer> arg_rgb)
{
    const auto [r, g, b] = arg_rgb;
    const std::array<int, 36> alpha{{255,255,255,255,255,255, 255,255,224,128,68,40, 255,224,68,0,0,0, 255,128,0,0,0,0, 255,68,0,0,0,0, 255,40,0,0,0,0}};
    auto make = [&](bool flipx, bool flipy) {
        auto surface = std::make_shared<::cw::lib::Surface>(); surface->size = {6,6}; surface->rgba.resize(6 * 6 * 4);
        for (int y = 0; y < 6; ++y) for (int x = 0; x < 6; ++x) {
            const auto sx = flipx ? 5 - x : x, sy = flipy ? 5 - y : y; const auto pos = static_cast<std::size_t>((y * 6 + x) * 4);
            surface->rgba[pos] = static_cast<std::uint8_t>(std::clamp<::cw::lib::Integer>(r, 0, 255)); surface->rgba[pos + 1] = static_cast<std::uint8_t>(std::clamp<::cw::lib::Integer>(g, 0, 255)); surface->rgba[pos + 2] = static_cast<std::uint8_t>(std::clamp<::cw::lib::Integer>(b, 0, 255)); surface->rgba[pos + 3] = static_cast<std::uint8_t>(alpha[sy * 6 + sx]);
        }
        return surface;
    };
    return {make(false, false), make(true, false), make(false, true), make(true, true)};
}

void Resource::draw_frame(std::shared_ptr<::cw::lib::Surface> arg_bmp, std::shared_ptr<::cw::lib::Object> arg_rect, std::tuple<::cw::lib::Integer, ::cw::lib::Integer, ::cw::lib::Integer> arg_color)
{
    if (!arg_bmp) return;
    const auto [r, g, b] = arg_color; const auto w = arg_bmp->size.width; const auto h = arg_bmp->size.height;
    if (w <= 0 || h <= 0 || arg_bmp->rgba.size() < static_cast<std::size_t>(w * h * 4)) return;
    ::cw::lib::Rect rect{0, 0, w, h};
    if (const auto typed = std::dynamic_pointer_cast<::cw::RectValue>(arg_rect)) rect = typed->rect;
    const auto x0 = rect.x;
    const auto y0 = rect.y;
    const auto x1 = rect.x + rect.width - 1;
    const auto y1 = rect.y + rect.height - 1;
    const auto paint = [&](::cw::lib::Integer x, ::cw::lib::Integer y) {
        if (x < 0 || y < 0 || x >= w || y >= h) return;
        const auto p = static_cast<std::size_t>((y * w + x) * 4);
        arg_bmp->rgba[p] = static_cast<std::uint8_t>(std::clamp<::cw::lib::Integer>(r, 0, 255));
        arg_bmp->rgba[p + 1] = static_cast<std::uint8_t>(std::clamp<::cw::lib::Integer>(g, 0, 255));
        arg_bmp->rgba[p + 2] = static_cast<std::uint8_t>(std::clamp<::cw::lib::Integer>(b, 0, 255));
        arg_bmp->rgba[p + 3] = 255;
    };
    for (::cw::lib::Integer x = std::max<::cw::lib::Integer>(0, x0);
         rect.width > 0 && rect.height > 0 && x <= std::min<::cw::lib::Integer>(w - 1, x1); ++x) {
        paint(x, y0); paint(x, y1);
    }
    for (::cw::lib::Integer y = std::max<::cw::lib::Integer>(0, y0);
         rect.width > 0 && rect.height > 0 && y <= std::min<::cw::lib::Integer>(h - 1, y1); ++y) {
        paint(x0, y); paint(x1, y);
    }
    const auto [top_left, top_right, bottom_left, bottom_right] = create_cornerimg(arg_color);
    alpha_blit(*top_left, *arg_bmp, rect.x, rect.y);
    alpha_blit(*top_right, *arg_bmp, rect.x + rect.width - 6, rect.y);
    alpha_blit(*bottom_left, *arg_bmp, rect.x, rect.y + rect.height - 6);
    alpha_blit(*bottom_right, *arg_bmp, rect.x + rect.width - 6, rect.y + rect.height - 6);
    subtract_corner_alpha(*arg_bmp, rect, 0);
}

void Resource::draw_corneroutimg(std::shared_ptr<::cw::lib::Surface> arg_bmp, std::optional<std::shared_ptr<::cw::lib::Object>> arg_rect, ::cw::lib::Integer arg_outframe)
{
    if (!arg_bmp || arg_bmp->rgba.empty()) return;
    const auto w = arg_bmp->size.width, h = arg_bmp->size.height;
    ::cw::lib::Rect rect{0, 0, w, h};
    if (arg_rect && *arg_rect) {
        if (const auto typed = std::dynamic_pointer_cast<::cw::RectValue>(*arg_rect)) rect = typed->rect;
    }
    subtract_corner_alpha(*arg_bmp, rect, arg_outframe);
}

std::shared_ptr<::cw::lib::Surface> Resource::_create_statusbtnbmp(::cw::lib::Integer arg_w, ::cw::lib::Integer arg_h, ::cw::lib::Integer arg_flags)
{
    auto bmp = std::make_shared<::cw::lib::Surface>();
    bmp->size = {std::max<::cw::lib::Integer>(1, arg_w), std::max<::cw::lib::Integer>(1, arg_h)};
    const auto w = bmp->size.width;
    const auto h = bmp->size.height;
    fill_surface(*bmp, 0, 0, 0, 0);
    const bool disabled = (arg_flags & g_SB_DISABLE) != 0;
    const bool pressed = (arg_flags & g_SB_PRESSED) != 0;
    const bool current = (arg_flags & g_SB_CURRENT) != 0;
    const bool notice = (arg_flags & g_SB_NOTICE) != 0;
    const bool emphasize = (arg_flags & g_SB_EMPHASIZE) != 0;
    const auto [r1, g1, b1, r2, g2, b2] = [&] {
        if (disabled) return std::array<::cw::lib::Integer, 6>{{240, 240, 240, 240, 240, 240}};
        if (pressed && current) return std::array<::cw::lib::Integer, 6>{{234, 234, 234, 222, 222, 222}};
        if (pressed) return std::array<::cw::lib::Integer, 6>{{220, 220, 220, 208, 208, 208}};
        if (current) return std::array<::cw::lib::Integer, 6>{{255, 255, 255, 250, 250, 250}};
        return std::array<::cw::lib::Integer, 6>{{255, 255, 255, 232, 232, 232}};
    }();
    if (disabled) {
        fill_surface(*bmp, r1, g1, b1);
    } else {
        const auto middle = h / 2;
        for (::cw::lib::Integer y = 0; y <= middle; ++y) {
            // pygame と同様、描画面外の行は切り捨てる。 範囲内へ収
            // めると、偶数の高さで最後の有効な勾配行を上書きしてしまう。
            const auto upper = middle - y;
            const auto lower = middle + y;
            for (::cw::lib::Integer x = 0; x < w; ++x) {
                paint_pixel(*bmp, x, upper, r1 - y / 4, g1 - y / 4, b1 - y / 4);
                paint_pixel(*bmp, x, lower, r2 - y, g2 - y, b2 - y);
            }
        }
    }
    auto corners = create_cornerimg({208, 208, 208});
    auto subtract_corners = [&](::cw::lib::Integer value) {
        for (const auto& corner : {std::get<0>(corners), std::get<1>(corners), std::get<2>(corners), std::get<3>(corners)})
            subtract_rgb(*corner, value, value, value);
    };
    auto blit_corners = [&](::cw::lib::Integer left, ::cw::lib::Integer top,
                            ::cw::lib::Integer right, ::cw::lib::Integer bottom,
                            bool include_bottom = true) {
        alpha_blit(*std::get<0>(corners), *bmp, left, top);
        alpha_blit(*std::get<1>(corners), *bmp, right, top);
        if (include_bottom) {
            alpha_blit(*std::get<2>(corners), *bmp, left, bottom);
            alpha_blit(*std::get<3>(corners), *bmp, right, bottom);
        }
    };
    if (pressed) {
        if (!current) subtract_corners(8);
        draw_horizontal(*bmp, 2, w - 4, 3, current ? 208 : 200, current ? 208 : 200, current ? 208 : 200);
        subtract_corners(8);
        blit_corners(2, 3, w - 7, h - 7, false);
        draw_outline(*bmp, {2, 2, w - 3, h - 3}, current ? 200 : 192, current ? 200 : 192, current ? 200 : 192);
        blit_corners(2, 2, w - 7, h - 7, false);
        alpha_blit(*std::get<2>(corners), *bmp, 2, h - 7);
        subtract_corners(64);
    } else if (disabled) {
        subtract_corners(16);
    } else {
        subtract_corners(72);
    }
    // Py と同様、DISABLE も設定されていても押下時の分岐を優先する。
    ::cw::lib::Integer line_r = disabled && !pressed ? 192 : 128;
    ::cw::lib::Integer line_g = disabled && !pressed ? 192 : 128;
    ::cw::lib::Integer line_b = disabled && !pressed ? 192 : 128;
    if (emphasize) {
        for (const auto& corner : {std::get<0>(corners), std::get<1>(corners), std::get<2>(corners), std::get<3>(corners)}) {
            subtract_rgb(*corner, 0, 128, 128);
            add_rgb(*corner, 96, 0, 0);
        }
        line_r = std::min<::cw::lib::Integer>(255, line_r + 96);
        line_g = std::max<::cw::lib::Integer>(0, line_g - 128);
        line_b = std::max<::cw::lib::Integer>(0, line_b - 128);
    }
    const auto corner_alpha = (!current && !disabled) ? 163 : 255;
    if (!current && !disabled) {
        // Py と同様、辺の線のアルファ設定だけでなく角の画像自身か
        // らも不透明度を引く。 透明なピクセルは範囲内に維持する。
        for (const auto& corner : {std::get<0>(corners), std::get<1>(corners), std::get<2>(corners), std::get<3>(corners)})
            for (std::size_t i = 3; i < corner->rgba.size(); i += 4)
                corner->rgba[i] = static_cast<std::uint8_t>(std::max<int>(0, corner->rgba[i] - 92));
    }
    draw_outline(*bmp, {1, 1, w - 2, h - 2}, line_r, line_g, line_b, corner_alpha);
    blit_corners(1, 1, w - 7, h - 7);
    if (!pressed) {
        static constexpr std::array<int, 36> highlight_alpha{{0, 0, 128, 255, 255, 255,
            0, 196, 224, 128, 68, 40,
            128, 224, 68, 0, 0, 0,
            255, 128, 0, 0, 0, 0,
            255, 68, 0, 0, 0, 0,
            255, 40, 0, 0, 0, 0}};
        auto make_highlight = [&](bool flip_x, bool flip_y) {
            auto surface = std::make_shared<::cw::lib::Surface>();
            surface->size = {6, 6};
            surface->rgba.resize(6 * 6 * 4);
            for (::cw::lib::Integer y = 0; y < 6; ++y) for (::cw::lib::Integer x = 0; x < 6; ++x) {
                const auto sx = flip_x ? 5 - x : x;
                const auto sy = flip_y ? 5 - y : y;
                paint_pixel(*surface, x, y, r1, g1, b1, highlight_alpha[static_cast<std::size_t>(sy * 6 + sx)]);
            }
            return surface;
        };
        const auto highlight_top_left = make_highlight(false, false);
        const auto highlight_top_right = make_highlight(true, false);
        const auto highlight_bottom_left = make_highlight(false, true);
        const auto highlight_bottom_right = make_highlight(true, true);
        draw_horizontal(*bmp, 8, w - 9, 2, r1, g1, b1);
        draw_horizontal(*bmp, 8, w - 9, h - 3, r1, g1, b1);
        draw_vertical(*bmp, 2, 8, h - 9, r1, g1, b1);
        draw_vertical(*bmp, w - 3, 8, h - 9, r1, g1, b1);
        alpha_blit(*highlight_top_left, *bmp, 2, 2);
        alpha_blit(*highlight_top_right, *bmp, w - 8, 2);
        alpha_blit(*highlight_bottom_left, *bmp, 2, h - 8);
        alpha_blit(*highlight_bottom_right, *bmp, w - 8, h - 8);
    }
    if (notice) {
        add_rgb(*bmp, pressed ? 64 : 128, 0, 0);
        // Py と同様、ここでは三成分の色を BLEND_RGBA_ADD で塗
        // る。 暗黙のアルファは 255 なので、全ピクセルを不透明にした後、
        // draw_corneroutimg が外側の角のアルファを再び引く。
        ::cw::lib::simd_image::force_alpha(bmp->rgba.data(), bmp->rgba.size() / 4, 255);
        subtract_rgb(*bmp, 0, 96, 96);
    }
    subtract_corner_alpha(*bmp, {0, 0, w, h}, 1);
    draw_outline(*bmp, {0, 0, w, h}, 0, 0, 0, 0);
    return bmp;
}

std::optional<std::shared_ptr<::cw::lib::Surface>> Resource::get_statusbtnbmp(::cw::lib::Integer arg_sizetype, ::cw::lib::Integer arg_flags)
{
    if (arg_sizetype < 0 || arg_sizetype > 2) return std::nullopt;
    auto* table = arg_sizetype == 0 ? &m__statusbtnbmp0 : arg_sizetype == 1 ? &m__statusbtnbmp1 : &m__statusbtnbmp2;
    const auto it = table->find(arg_flags); if (it != table->end()) return std::make_shared<::cw::lib::Surface>(*it->second);
    const auto scaled = [](::cw::lib::Integer value) {
        // Py と同様、キャッシュ寸法には小数倍率の切り捨ても含む cw.s
        // を使う。 ここで丸めず、その公開変換を再利用する。
        return std::get<::cw::lib::Integer>(::cw::s(::cw::lib::Value(value)).storage());
    };
    const auto [w, h] = arg_sizetype == 0
        ? std::tuple<::cw::lib::Integer, ::cw::lib::Integer>{scaled(120), scaled(22)}
        : arg_sizetype == 1
            ? std::tuple<::cw::lib::Integer, ::cw::lib::Integer>{scaled(27), scaled(27)}
            : std::tuple<::cw::lib::Integer, ::cw::lib::Integer>{scaled(632), scaled(33)};
    auto bmp = _create_statusbtnbmp(w, h, arg_flags); (*table)[arg_flags] = bmp; return std::make_shared<::cw::lib::Surface>(*bmp);
}

::cw::lib::Value Resource::get_resources(::cw::lib::Callback arg_func, ::cw::lib::String arg_dpath1, ::cw::lib::String arg_dpath2, ::cw::lib::Integer arg_ext, std::optional<bool> arg_mask, std::optional<::cw::lib::Callback> arg_ss, std::vector<::cw::lib::String> arg_noresize, bool arg_nodbg, std::optional<::cw::lib::Callback> arg_emptyfunc, std::optional<::cw::lib::String> arg_editor_res, bool arg_warning, bool arg_can_loaded_scaledimage)
{
    // Python版のnokeyfuncをResourceTableの遅延コールバックへ写す。
    // SDL/wxの画像型はCallbackの境界を越えられないため、画像ローダーへは
    // pathを位置引数、mask/scale情報をキーワード引数として渡す。
    auto table = std::make_shared<::cw::setting::ResourceTable>();
    // Pyとの差（寿命の境界）：Pyのクロージャはselfを生かし続けるが、ここでは
    // 遅延ローダーがthis（Resource）を借りる。標準のリソース生成経路は返す表を
    // Resourceのメンバーに保持するが、get_resourcesを直接呼ぶ側は表を独立して保持できる。
    // その場合、遅延ロードが終わるまでResourceを生存させる必要がある。
    table->initialize(arg_dpath1, std::nullopt, arg_emptyfunc,
        [this, arg_func, arg_dpath1, arg_dpath2, arg_ext, arg_mask, arg_ss, arg_noresize, arg_nodbg,
         arg_emptyfunc, arg_editor_res, arg_warning, arg_can_loaded_scaledimage](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
            const auto requested = args.empty() ? ::cw::lib::String{} : resource_key(args.front());
            bool dbg = !arg_nodbg && requested.ends_with("_dbg");
            bool noscale = requested.ends_with("_noscale");
            auto key = requested;
            std::optional<::cw::lib::Integer> up_scr;
            if (dbg) { key.resize(key.size() - 4); up_scr = ::cw::g_dpi_level; }
            if (noscale) key.resize(key.size() - 8);

            auto find_path = [&](const ::cw::lib::String& root) {
                return ::cw::util::find_resource(
                    ::cw::util::join_paths({::cw::lib::Value(root), ::cw::lib::Value(key)}), arg_ext);
            };
            ::cw::lib::String path;
            if (arg_editor_res && !arg_editor_res->empty()) {
                const auto it = g_CWXEDITOR_RESOURCES.find(key);
                if (it != g_CWXEDITOR_RESOURCES.end()) {
                    const auto candidate = std::filesystem::u8path(*arg_editor_res) / std::filesystem::u8path(it->second);
                    if (std::filesystem::is_regular_file(candidate)) path = get_filepath(path_utf8(candidate));
                }
            }
            if (path.empty() && !arg_dpath2.empty()) path = find_path(arg_dpath2);
            if (path.empty()) path = find_path(arg_dpath1);
            if (path.empty()) {
                if (arg_warning) {
                    const auto directory = path_utf8(std::filesystem::u8path(arg_dpath1).filename());
                    queue_resource_error("リソース [" + directory + "/" + key + "] が見つかりません。\n"
                        "デイリービルド版でこのエラーが発生した場合は、「Data/SkinBase」以下のリソースが最新版になっていない可能性があります。",
                        "Resource [" + directory + "/" + key + "] is not found.");
                }
                // リソース欠落時のemptyfunc必須チェックも遅延コールバック内で行い
                // 、そのチェックや代替生成の失敗をLazyResourceに記録させる。
                if (!arg_emptyfunc || !*arg_emptyfunc)
                    throw std::runtime_error("Missing resource has no empty callback");
                return (*arg_emptyfunc)({}, {});
            }
            ::cw::lib::Value result;
            if (arg_func) {
                ::cw::lib::KeywordArguments kwargs;
                if (arg_mask) {
                    kwargs.emplace("mask", ::cw::lib::Value(*arg_mask));
                    kwargs.emplace("can_loaded_scaledimage", ::cw::lib::Value(arg_can_loaded_scaledimage));
                    kwargs.emplace("up_scr", up_scr ? ::cw::lib::Value(*up_scr) : ::cw::lib::Value{});
                }
                // 画像/音声の実装側が例外を返した場合はLazyResourceがfailureを記録する。
                result = arg_func({::cw::lib::Value(path)}, kwargs);
            } else {
                // Callback未指定時もpathだけを捨てず、SDL接続前のportable画像を返す。
                const auto image = ::cw::util::load_image(path, arg_mask.value_or(false), {0, 0}, std::nullopt, true, false,
                                                            arg_can_loaded_scaledimage, noscale, up_scr ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up_scr)) : std::nullopt, false);
                result = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
            }
            if (arg_ss && *arg_ss && !noscale) {
                if (dbg) result = ::cw::ppis(result);
                else if (std::find(arg_noresize.begin(), arg_noresize.end(), key) == arg_noresize.end())
                    result = (*arg_ss)({result}, {});
            }
            return result;
        });
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
}

::cw::lib::Value Resource::get_sounds(std::shared_ptr<::cw::setting::Setting> arg_setting, ::cw::lib::Value arg_skinsounds)
{
    auto table = std::make_shared<::cw::setting::ResourceTable>();
    table->initialize("SystemSound", std::nullopt,
        [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(make_setting_sound({}, false)));
        }, std::nullopt);
    std::shared_ptr<::cw::setting::ResourceTable> skin_table;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_skinsounds.storage()); object && *object)
        skin_table = std::dynamic_pointer_cast<::cw::setting::ResourceTable>(*object);
    if (arg_setting) for (const auto& [key, value] : arg_setting->m_sound_table) {
        const auto sound_key = resource_key(value);
        auto callback = [skin_table, sound_key](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
            if (skin_table && skin_table->contains(::cw::lib::Value(sound_key))) return skin_table->get_item(::cw::lib::Value(sound_key));
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(make_setting_sound({}, false)));
        };
        table->set(key, std::move(callback), {}, {});
    }
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
}

::cw::lib::Value Resource::get_skinsounds()
{
    auto loader = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
        const auto path = callback_path(args);
        auto sound = make_setting_sound(path, ::cw::util::is_midi(path));
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(sound));
    };
    return get_resources(loader, "Data/SkinBase/Sound", path_utf8(std::filesystem::u8path(m_skindir) / "Sound"), m_ext_snd, false, std::nullopt, {}, false, std::nullopt, std::nullopt, false, true);
}

std::shared_ptr<::cw::setting::MsgDict> Resource::get_msgs(std::shared_ptr<::cw::setting::Setting> arg_setting)
{
    if (arg_setting && arg_setting->m_msgs) return arg_setting->m_msgs;
    return std::make_shared<::cw::setting::MsgDict>();
}

::cw::lib::Value Resource::get_buttons()
{
    auto loader = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
        const auto up = callback_integer(kwargs, "up_scr");
        const auto path = callback_path(args);
        // ボタンはキャッシュするダイアログ素材だが、入力画像が静止画とは限らな
        // い。 読み込み境界から Bitmap として保持し、wins() が
        // 選択ファイルの倍率だけでなくアニメーション枠も引き継げるようにする。
        auto bitmap = ::cw::util::load_wxbmp(path, callback_bool(kwargs, "mask", true),
            {}, {}, std::nullopt, true,
            callback_bool(kwargs, "can_loaded_scaledimage", true),
            callback_bool(kwargs, "noscale", false),
            up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt);
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(bitmap));
    };
    ::cw::lib::Callback ss = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
        return args.empty() ? ::cw::lib::Value{} : ::cw::wins(args.front());
    };
    return get_resources(std::move(loader), "Data/SkinBase/Resource/Image/Button", path_utf8(std::filesystem::u8path(m_skindir) / "Resource/Image/Button"), m_ext_img, true, std::move(ss), {}, false,
                         ::cw::lib::Callback([](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_wxbmp())); }), std::nullopt, true, true);
}

::cw::lib::Value Resource::get_cursors()
{
    auto default_cursor = [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
        const auto native = backend();
        auto cursor = native && native->create_cursor ? native->create_cursor("CURSOR_ARROW", {}) : create_native_cursor("CURSOR_ARROW", {});
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(cursor));
    };
    auto get_cursor = [this](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) {
        const auto name = callback_path(args); const auto filename = name + ".cur";
        for (const auto& root : {std::filesystem::u8path("Data/SkinBase/Resource/Image/Cursor"), std::filesystem::u8path(m_skindir) / "Resource/Image/Cursor"}) {
            const auto path = root / std::filesystem::u8path(filename);
            if (std::filesystem::is_regular_file(path)) {
                const auto native = backend();
                auto cursor = native && native->create_cursor
                    ? native->create_cursor(name, path_utf8(path))
                    : create_native_cursor(name, path_utf8(path));
                return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(cursor));
            }
        }
        const auto cursor_name = name.empty() ? ::cw::lib::String{"CURSOR_ARROW"} : name;
        const auto native = backend();
        auto cursor = native && native->create_cursor
            ? native->create_cursor(cursor_name, {})
            : create_native_cursor(cursor_name, {});
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(cursor));
    };
    auto table = std::make_shared<::cw::setting::ResourceTable>(); table->initialize("Resource/Image/Cursor", std::nullopt, std::move(default_cursor), std::move(get_cursor));
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
}

::cw::lib::Value Resource::get_stones()
{
    auto loader = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
        const auto up = callback_integer(kwargs, "up_scr");
        const auto image = ::cw::util::load_image(callback_path(args), callback_bool(kwargs, "mask", true), {0, 0}, std::nullopt, true, false,
                                                   callback_bool(kwargs, "can_loaded_scaledimage", true), callback_bool(kwargs, "noscale", false),
                                                   up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt, false);
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
    };
    const auto ss = ::cw::lib::Callback(
        [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
            if (args.empty()) return {};
            return ::cw::s(args.front());
        });
    return get_resources(std::move(loader), "Data/SkinBase/Resource/Image/Stone", path_utf8(std::filesystem::u8path(m_skindir) / "Resource/Image/Stone"), m_ext_img, true, ss, {}, false,
                         ::cw::lib::Callback([](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_image())); }), std::nullopt, true, true);
}

::cw::lib::Value Resource::get_wxstones()
{
    auto loader = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
        const auto up = callback_integer(kwargs, "up_scr");
        auto bitmap = ::cw::util::load_wxbmp(callback_path(args),
            callback_bool(kwargs, "mask", true), {}, {}, std::nullopt, true,
            callback_bool(kwargs, "can_loaded_scaledimage", true),
            callback_bool(kwargs, "noscale", false),
            up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt);
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(bitmap));
    };
    const auto ss = ::cw::lib::Callback(
        [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
            if (args.empty()) return {};
            return ::cw::wins(args.front());
        });
    return get_resources(std::move(loader), "Data/SkinBase/Resource/Image/Stone", path_utf8(std::filesystem::u8path(m_skindir) / "Resource/Image/Stone"), m_ext_img, true, ss, {}, false,
                         ::cw::lib::Callback([](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_wxbmp())); }), std::nullopt, true, true);
}

::cw::lib::Value Resource::get_statuses(::cw::lib::Callback arg_load_image, bool arg_for_wx)
{
    if (!arg_load_image) {
        arg_load_image = [arg_for_wx](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
            const auto path = callback_path(args);
            const auto key = path_utf8(std::filesystem::u8path(path).stem());
            bool mask = false;
            std::tuple<::cw::lib::Integer, ::cw::lib::Integer> maskpos{0, 0};
            if (key == "LIFE" || key == "UP0" || key == "UP1" || key == "UP2" || key == "UP3" ||
                key == "DOWN0" || key == "DOWN1" || key == "DOWN2" || key == "DOWN3") {
                mask = true; maskpos = {1, 1};
            } else if (key == "LIFEGUAGE") {
                mask = true; maskpos = {5, 5};
            } else if (key == "LIFEGUAGE2" || key == "LIFEGUAGE2_MASK") {
                mask = true;
            } else if (key == "LIFEBAR") {
                mask = false;
            }
            const auto up = callback_integer(kwargs, "up_scr");
            if (key == "TARGET") return Resource_get_statuses_load_image2(path, true, callback_bool(kwargs, "can_loaded_scaledimage", true), up);
            std::shared_ptr<::cw::lib::Surface> image;
            if (arg_for_wx) {
                auto position = std::make_shared<::cw::data::VariantSequence>();
                position->m_values = {::cw::lib::Value(std::get<0>(maskpos)),
                                      ::cw::lib::Value(std::get<1>(maskpos))};
                image = ::cw::util::load_wxbmp(path, mask, {},
                    ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(position)),
                    std::nullopt, true,
                    callback_bool(kwargs, "can_loaded_scaledimage", true),
                    callback_bool(kwargs, "noscale", false),
                    up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt);
            } else {
                image = ::cw::util::load_image(path, mask, maskpos, std::nullopt, true, false,
                    callback_bool(kwargs, "can_loaded_scaledimage", true),
                    callback_bool(kwargs, "noscale", false),
                    up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt, false);
            }
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
        };
    }
    ::cw::lib::Callback ss = ::cw::lib::Callback(
        [arg_for_wx](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
            if (args.empty()) return {};
            return arg_for_wx ? ::cw::wins(args.front()) : ::cw::s(args.front());
        });
    return get_resources(std::move(arg_load_image), "Data/SkinBase/Resource/Image/Status", path_utf8(std::filesystem::u8path(m_skindir) / "Resource/Image/Status"), m_ext_img, false, std::move(ss), {}, false,
                         ::cw::lib::Callback([](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_image())); }), std::nullopt, true, true);
}

::cw::lib::Value Resource::get_dialogs(::cw::lib::Callback arg_load_image, ::cw::lib::Callback arg_emptyfunc, bool arg_for_wx)
{
    if (!arg_load_image) {
        arg_load_image = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
            const auto path = callback_path(args); const auto key = path_utf8(std::filesystem::u8path(path).stem());
            // Python の get_dialogs() と同様、通常のダイアログ用記号には
            // get_resources(mask=True) を渡す。 省くと HELP/SETTINGS
            // の黒い透過色が不透明となり、ステータスバーボタン全体を覆ってしまう。
            const bool mask = callback_bool(kwargs, "mask", false);
            const auto up = callback_integer(kwargs, "up_scr");
            if (key == "STATUS8") return Resource_get_statuses_load_image2(path, true, callback_bool(kwargs, "can_loaded_scaledimage", true), up);
            // Python の get_dialogs() と同様、タイル背景は透過色なし
            // で読む。 CAUTION にマスクを付けると、拡縮前に基本色が消えてしまう。
            const bool effective_mask = key == "LINK" || key == "MONEYY" ||
                key == "CAUTION" || key == "INVISIBLE" ? false : mask;
            const auto image = ::cw::util::load_wxbmp(path, effective_mask, {}, {}, std::nullopt,
                true, callback_bool(kwargs, "can_loaded_scaledimage", true),
                callback_bool(kwargs, "noscale", false),
                up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt);
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
        };
    }
    if (!arg_emptyfunc) arg_emptyfunc = [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_image())); };
    ::cw::lib::Callback ss = [arg_for_wx](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
        if (args.empty()) return {};
        return arg_for_wx ? ::cw::wins(args.front()) : ::cw::s(args.front());
    };
    return get_resources(std::move(arg_load_image), "Data/SkinBase/Resource/Image/Dialog", path_utf8(std::filesystem::u8path(m_skindir) / "Resource/Image/Dialog"), m_ext_img, true, std::move(ss), {}, false, std::move(arg_emptyfunc), std::nullopt, true, true);
}

::cw::lib::Value Resource::get_debugs(::cw::lib::Callback arg_load_image, ::cw::lib::Callback arg_emptyfunc, ::cw::lib::Callback arg_ss, bool arg_can_loaded_scaledimage)
{
    if (!arg_load_image) arg_load_image = [](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
        const auto up = callback_integer(kwargs, "up_scr");
        const auto image = ::cw::util::load_wxbmp(callback_path(args), callback_bool(kwargs, "mask", true), {}, {}, std::nullopt,
            true, callback_bool(kwargs, "can_loaded_scaledimage", true),
            callback_bool(kwargs, "noscale", false),
            up ? std::optional<::cw::lib::Value>(::cw::lib::Value(*up)) : std::nullopt);
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
    };
    if (!arg_emptyfunc) arg_emptyfunc = [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_image())); };
    std::optional<::cw::lib::String> editor_res;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_setting.storage()); object && *object) {
        if (const auto setting = std::dynamic_pointer_cast<::cw::setting::Setting>(*object); setting && !setting->m_editor.empty()) {
            const auto editor = std::filesystem::absolute(std::filesystem::u8path(setting->m_editor));
            const auto resource = editor.parent_path() / "resource";
            if (std::filesystem::is_directory(resource)) editor_res = path_utf8(resource);
        }
    }
    return get_resources(std::move(arg_load_image), "Data/Debugger", "", m_ext_img, true, std::move(arg_ss), {}, false, std::move(arg_emptyfunc), editor_res, true, arg_can_loaded_scaledimage);
}

::cw::lib::Value Resource::get_cardbgs(::cw::lib::Callback arg_load_image, ::cw::lib::Callback arg_emptyfunc, bool arg_for_wx)
{
    if (!arg_load_image) arg_load_image = [arg_for_wx](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments& kwargs) {
        auto image = load_card_background(callback_path(args), callback_bool(kwargs, "mask", false),
            arg_for_wx, callback_bool(kwargs, "can_loaded_scaledimage", true),
            callback_bool(kwargs, "noscale", false), callback_integer(kwargs, "up_scr"));
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
    };
    if (!arg_emptyfunc) arg_emptyfunc = [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_image())); };
    // Python の get_cardbgs() と同様、pygame 用 cardbgs は cw.s、wxcardbgs は cw.wins を使う。
    ::cw::lib::Callback ss = ::cw::lib::Callback(
        [arg_for_wx](const ::cw::lib::Arguments& args, const ::cw::lib::KeywordArguments&) -> ::cw::lib::Value {
            if (args.empty()) return {};
            return arg_for_wx ? ::cw::wins(args.front()) : ::cw::s(args.front());
        });
    return get_resources(std::move(arg_load_image), "Data/SkinBase/Resource/Image/CardBg", path_utf8(std::filesystem::u8path(m_skindir) / "Resource/Image/CardBg"), m_ext_img, false, std::move(ss), {}, true, std::move(arg_emptyfunc), std::nullopt, true, true);
}

::cw::lib::Value Resource::get_cardnamecolorhints(::cw::lib::Value arg_cardbgs)
{
    auto table = std::make_shared<::cw::setting::ResourceTable>();
    table->initialize("CardBgColorHints", std::nullopt,
        [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) { return ::cw::lib::Value(static_cast<::cw::lib::Integer>(255)); }, std::nullopt);
    std::shared_ptr<::cw::setting::ResourceTable> card_table;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_cardbgs.storage()); object && *object) card_table = std::dynamic_pointer_cast<::cw::setting::ResourceTable>(*object);
    for (const auto& key : {"ACTION", "BEAST", "BIND", "DANGER", "FAINT", "INFO", "INJURY", "ITEM", "LARGE", "NORMAL", "OPTION", "PARALY", "PETRIF", "SKILL", "SLEEP"}) {
        const ::cw::lib::String name(key);
        table->set(name, [this, card_table, name](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
            if (!card_table) return ::cw::lib::Value(static_cast<::cw::lib::Integer>(255));
            const auto value = card_table->get_item(::cw::lib::Value(name));
            if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage()); object && *object) {
                if (const auto image = std::dynamic_pointer_cast<::cw::lib::Surface>(*object)) return ::cw::lib::Value(calc_cardnamecolorhint(image));
            }
            return ::cw::lib::Value(static_cast<::cw::lib::Integer>(255));
        }, {}, {});
    }
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
}

::cw::lib::Integer Resource::calc_cardnamecolorhint(std::shared_ptr<::cw::lib::Surface> arg_bmp)
{
    // Py と同様、cw.s の各座標を独立して切り捨て、幅から cw.s(10)
    // を引く区間も維持する。 cw.s(5) の二倍では、小数倍率で結果が異なる。
    const auto scaled = [](::cw::lib::Integer value) {
        return std::get<::cw::lib::Integer>(::cw::s(::cw::lib::Value(value)).storage());
    };
    const auto sx = scaled(5), sy = scaled(5), margin = scaled(10), height = scaled(15);
    if (!arg_bmp || arg_bmp->size.width <= margin || arg_bmp->size.height <= scaled(20) || arg_bmp->rgba.empty()) return 255;
    const ::cw::lib::Integer x0 = sx, y0 = sy, x1 = sx + arg_bmp->size.width - margin, y1 = sy + height; std::uint64_t sum = 0; std::size_t count = 0;
    for (::cw::lib::Integer y = y0; y < y1; ++y) for (::cw::lib::Integer x = x0; x < x1; ++x) { const auto p = static_cast<std::size_t>((y * arg_bmp->size.width + x) * 4); if (p + 2 >= arg_bmp->rgba.size()) continue; sum += arg_bmp->rgba[p] + arg_bmp->rgba[p + 1] + arg_bmp->rgba[p + 2]; count += 3; }
    if (!count) throw std::domain_error("card-name colour average has no pixels");
    return static_cast<::cw::lib::Integer>(sum / count);
}

::cw::lib::Integer Resource::calc_wxcardnamecolorhint(std::shared_ptr<::cw::lib::Bitmap> arg_wxbmp)
{
    return calc_cardnamecolorhint(std::move(arg_wxbmp));
}

std::map<::cw::lib::Integer, std::shared_ptr<::cw::header::CardHeader>> Resource::get_actioncards()
{
    std::map<::cw::lib::Integer, std::shared_ptr<::cw::header::CardHeader>> result;
    const auto directory = std::filesystem::u8path(m_skindir) / "Resource/Xml/ActionCard"; std::error_code ec;
    if (!std::filesystem::is_directory(directory, ec)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(directory, ec)) {
        if (ec || !entry.is_regular_file(ec) || entry.path().extension() != ".xml") continue;
        const auto element = ::cw::data::xml2element(path_utf8(entry.path()), "", std::nullopt, std::nullopt, false, std::nullopt); if (!element) continue;
        auto header = std::make_shared<::cw::header::CardHeader>(); header->initialize(std::nullopt, std::nullopt, std::optional<std::shared_ptr<::cw::data::CWPyElement>>(element), false, m_skindir, false, std::nullopt, std::nullopt, "", ""); result[header->m_id] = std::move(header);
    }
    return result;
}

std::map<::cw::lib::String, std::shared_ptr<::cw::header::CardHeader>> Resource::get_backpackcards()
{
    std::map<::cw::lib::String, std::shared_ptr<::cw::header::CardHeader>> result;
    auto path = std::filesystem::u8path(m_skindir) / "Resource/Xml/SpecialCard/UseCardInBackpack.xml"; if (!std::filesystem::is_regular_file(path)) path = std::filesystem::u8path("Data/SkinBase/Resource/Xml/SpecialCard/UseCardInBackpack.xml");
    const auto element = ::cw::data::xml2element(path_utf8(path), "", std::nullopt, std::nullopt, false, std::nullopt); if (!element) return result;
    // Python はキーを ItemCard/BeastCard、CardHeader の bgtype を ITEM/BEAST
    // として渡す。キーと背景種別を混同しないように型付きで保持する。
    for (const auto& [key, bgtype] : std::array<std::pair<const char*, const char*>, 2>{{{"ItemCard", "ITEM"}, {"BeastCard", "BEAST"}}}) {
        auto header = std::make_shared<::cw::header::CardHeader>();
        header->initialize(std::nullopt, std::nullopt, std::optional<std::shared_ptr<::cw::data::CWPyElement>>(element), false, m_skindir, false, std::nullopt, std::nullopt, "", bgtype);
        result[key] = std::move(header);
    }
    return result;
}

::cw::lib::Value Resource::get_specialchars()
{
    m_specialchars_is_changed = false;
    auto table = std::make_shared<::cw::setting::ResourceTable>();
    auto empty_special = [](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
        auto sequence = std::make_shared<::cw::data::VariantSequence>();
        sequence->m_values.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(empty_image())));
        sequence->m_values.emplace_back(false);
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(sequence));
    };
    table->initialize("Resource/Image/Font", std::nullopt, empty_special, std::nullopt);
    const std::map<::cw::lib::String, ::cw::lib::String> symbols{{"ANGRY", "#a"}, {"CLUB", "#b"}, {"DIAMOND", "#d"}, {"EASY", "#e"}, {"FLY", "#f"}, {"GRIEVE", "#g"}, {"HEART", "#h"}, {"JACK", "#j"}, {"KISS", "#k"}, {"LAUGH", "#l"}, {"NIKO", "#n"}, {"ONSEN", "#o"}, {"PUZZLE", "#p"}, {"QUICK", "#q"}, {"SPADE", "#s"}, {"WORRY", "#w"}, {"X", "#x"}, {"ZAP", "#z"}};
    for (const auto& [key, symbol] : symbols) {
        // Python の self の強参照とは異なり、不変な検索データだけを保持する。 ログ
        // が Resource の置き換え後もこのコールバックを保持しても、循環参照を作らない。
        auto callback = [skindir = m_skindir, ext_img = m_ext_img, key](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) {
            // Python と同様、find_resource が共通の SkinBase の代替を提供する。
            auto path = ::cw::util::find_resource(
                path_utf8(std::filesystem::u8path(skindir) / "Resource/Image/Font" / std::filesystem::u8path(key)), ext_img);
            auto image = path.empty() ? empty_image() : ::cw::util::load_image(path, true, {0, 0}, std::nullopt, true, false, true, false, std::nullopt, false);
            auto sequence = std::make_shared<::cw::data::VariantSequence>();
            sequence->m_values.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image)));
            sequence->m_values.emplace_back(false);
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(sequence));
        };
        table->set(symbol, std::move(callback), {}, {});
    }
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
}

void ResourceTable::initialize(::cw::lib::String arg_name, std::optional<::cw::lib::ValueMap> arg_init, std::optional<::cw::lib::Callback> arg_deffunc, std::optional<::cw::lib::Callback> arg_nokeyfunc)
{
    m_name_typed = std::move(arg_name); m_name = ::cw::lib::Value(m_name_typed); m_deffunc_typed = arg_deffunc.value_or(::cw::lib::Callback{}); m_nokeyfunc_typed = arg_nokeyfunc.value_or(::cw::lib::Callback{});
    m_entries.clear(); m_defload = false; m_defvalue.reset();
    if (arg_init) {
        for (const auto& [key, value] : *arg_init) {
            if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage()); object && *object) {
                if (const auto lazy = std::dynamic_pointer_cast<::cw::setting::LazyResource>(*object)) m_entries.emplace(key, lazy);
            }
            if (!m_entries.contains(key)) {
                auto lazy = std::make_shared<::cw::setting::LazyResource>();
                lazy->m__res = value; lazy->m_load = true; m_entries.emplace(key, std::move(lazy));
            }
        }
    }
}

void ResourceTable::reset()
{
    for (auto& [key, lazy] : m_entries) if (lazy) lazy->clear();
    // Python の reset と同様、個別の LazyResource
    // だけを消去し、 作成済みの空画像・音声などの既定値は再利用する。
}

void ResourceTable::merge(::cw::lib::Value arg_d)
{
    // 元の不具合を修正する。Python は self.dic を走査しながら self
    // にないキーを探すため、結合が何も行わない。 この公開 API では入力元
    // の結合、既存キーの優先、遅延リソースの同一性共有を維持する。 get_skinsounds
    // は Python の実際の Sound 表を維持する。
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_d.storage()); if (!object || !*object) return;
    const auto source = std::dynamic_pointer_cast<::cw::setting::ResourceTable>(*object); if (!source) return;
    for (const auto& [key, value] : source->m_entries) if (!m_entries.contains(key)) m_entries.emplace(key, value);
}

::cw::lib::Value ResourceTable::get_item(::cw::lib::Value arg_key)
{
    _put_nokeyvalue(arg_key);
    const auto key = resource_key(arg_key); const auto it = m_entries.find(key);
    if (it == m_entries.end() || !it->second) {
        if (!m_deffunc_typed)
            throw std::runtime_error("ResourceTable '" + m_name_typed + "' has no key '" + key + "'");
        return get_defvalue();
    }
    const auto value = it->second->get_res();
    if (it->second->m_failure) {
        if (!m_deffunc_typed)
            throw std::runtime_error("ResourceTable '" + m_name_typed + "' failed to load key '" + key + "'");
        return get_defvalue();
    }
    return value;
}

::cw::lib::Value ResourceTable::get_defvalue()
{
    if (!m_deffunc_typed) throw std::runtime_error("ResourceTable has no default resource");
    if (!m_defload) {
        m_defvalue = m_deffunc_typed({}, {});
        m_defload = true;
    }
    // Py と同様、既定のコールバックがキャッシュ済みでも None は拒否する。
    if (!m_defvalue || m_defvalue->is_none())
        throw std::runtime_error("ResourceTable default result is None");
    return *m_defvalue;
}

void ResourceTable::_put_nokeyvalue(::cw::lib::Value arg_key)
{
    const auto key = resource_key(arg_key); if (m_entries.contains(key) || !m_nokeyfunc_typed) return;
    auto lazy = std::make_shared<::cw::setting::LazyResource>();
    const auto callback = m_nokeyfunc_typed;
    lazy->initialize([callback, arg_key](const ::cw::lib::Arguments&, const ::cw::lib::KeywordArguments&) mutable -> ::cw::lib::Value {
        { return callback({arg_key}, {}); }}, {}, {});
    m_entries.emplace(key, std::move(lazy));
}

std::optional<::cw::lib::Value> ResourceTable::get(::cw::lib::Value arg_key, std::optional<::cw::lib::Value> arg_defvalue)
{
    _put_nokeyvalue(arg_key); const auto key = resource_key(arg_key); if (!m_entries.contains(key)) return arg_defvalue;
    return get_item(arg_key);
}

void ResourceTable::set(::cw::lib::Value arg_key, ::cw::lib::Callback arg_func, const ::cw::lib::Arguments& arg_args, const ::cw::lib::KeywordArguments& arg_kwargs)
{
    const auto key = resource_key(arg_key); if (key.empty()) return;
    auto lazy = std::make_shared<::cw::setting::LazyResource>();
    ::cw::lib::ValueMap kwargs; for (const auto& [name, value] : arg_kwargs) kwargs.emplace(name, value);
    lazy->initialize(std::move(arg_func), std::vector<::cw::lib::Value>(arg_args.begin(), arg_args.end()), std::move(kwargs));
    m_entries[key] = std::move(lazy);
}

void ResourceTable::remove(::cw::lib::Value arg_key)
{
    const auto key = resource_key(arg_key); const auto it = m_entries.find(key);
    if (it == m_entries.end()) throw std::out_of_range("ResourceTable key not found: " + key);
    m_entries.erase(it);
}

bool ResourceTable::contains(::cw::lib::Value arg_key)
{
    _put_nokeyvalue(arg_key); return m_entries.contains(resource_key(arg_key));
}

::cw::lib::Value ResourceTable::copy()
{
    auto table = std::make_shared<::cw::setting::ResourceTable>(); table->m_name_typed = m_name_typed; table->m_name = ::cw::lib::Value(m_name_typed); table->m_deffunc_typed = m_deffunc_typed; table->m_nokeyfunc_typed = m_nokeyfunc_typed; table->m_entries = m_entries; table->m_defload = m_defload; table->m_defvalue = m_defvalue;
    return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(table));
}

std::vector<::cw::lib::Value> ResourceTable::iterkeys()
{
    std::vector<::cw::lib::Value> result; result.reserve(m_entries.size()); for (const auto& [key, value] : m_entries) result.emplace_back(key); return result;
}

bool ResourceTable::is_loaded(::cw::lib::Value arg_key)
{
    _put_nokeyvalue(arg_key); const auto it = m_entries.find(resource_key(arg_key));
    if (it == m_entries.end() || !it->second) throw std::out_of_range("ResourceTable key not found");
    return it->second->m_load;
}

::cw::lib::Value ResourceTable::keys()
{
    auto sequence = std::make_shared<::cw::data::VariantSequence>(); for (const auto& key : iterkeys()) sequence->m_values.push_back(key); return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(sequence));
}

void ScenarioCompatibilityTable::initialize()
{
    m_table.clear();
}

void ScenarioCompatibilityTable::init()
{
    m_table.clear();
    const auto data = ::cw::data::xml2element("Data/Compatibility.xml", "", std::nullopt, std::nullopt, false, std::nullopt);
    if (!data) return;
    for (const auto& element : data->m_children) {
        if (!element) continue;
        const auto key = element->get("md5", "");
        const auto engine = element->m_text;
        const auto zindex = element->get("zIndexMode", "");
        const auto vanish = element->getbool(".", ::cw::lib::Value("enableVanishMemberCancellation"), false);
        // セキュリティ上、ゴシップ／終了印の復元無効化フラグはPython版同様に固定無効。
        if (!key.empty() && (!engine.empty() || !zindex.empty() || vanish)) m_table[key] = {engine, zindex, vanish, false, false};
    }
}

std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> ScenarioCompatibilityTable::get_versionhint(std::optional<::cw::lib::String> arg_fpath, std::optional<::cw::lib::Bytes> arg_filedata)
{
    ::cw::lib::String key;
    if (arg_filedata && !arg_filedata->empty()) key = ::cw::util::get_md5_from_data(*arg_filedata);
    else if (arg_fpath) key = ::cw::util::get_md5(*arg_fpath);
    else throw std::invalid_argument("ScenarioCompatibilityTable.get_versionhint requires fpath when filedata is empty");
    if (key.empty()) return std::nullopt;
    const auto it = m_table.find(key); return it == m_table.end() ? std::nullopt : std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>>(it->second);
}

bool ScenarioCompatibilityTable::lessthan(::cw::lib::String arg_versionhint, std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_currentversion)
{
    if (!arg_currentversion || arg_versionhint.empty() || std::get<0>(*arg_currentversion).empty()) {
        return false;
    }
    double hint = 0.0;
    double current = 0.0;
    return parse_python_float(arg_versionhint, hint) &&
           parse_python_float(std::get<0>(*arg_currentversion), current) && current <= hint;
}

bool ScenarioCompatibilityTable::zindexmode(std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_currentversion)
{
    if (!arg_currentversion) return false;
    const auto& explicit_mode = std::get<1>(*arg_currentversion);
    if (explicit_mode.empty()) return lessthan("1.20", arg_currentversion);
    double mode = 0.0;
    return parse_python_float(explicit_mode, mode) && mode <= 1.20;
}

bool ScenarioCompatibilityTable::enable_vanishmembercancellation(std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_currentversion)
{
    return arg_currentversion && std::get<2>(*arg_currentversion);
}

bool ScenarioCompatibilityTable::disable_gossiprestration(std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_currentversion)
{
    return arg_currentversion && std::get<3>(*arg_currentversion);
}

bool ScenarioCompatibilityTable::disable_compstamprestration(std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_currentversion)
{
    return arg_currentversion && std::get<4>(*arg_currentversion);
}

std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> ScenarioCompatibilityTable::merge_versionhints(std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_hint1, std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_hint2)
{
    if (!arg_hint1) return arg_hint2;
    if (!arg_hint2) return arg_hint1;
    return std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>{
        std::get<0>(*arg_hint1).empty() ? std::get<0>(*arg_hint2) : std::get<0>(*arg_hint1),
        std::get<1>(*arg_hint1).empty() ? std::get<1>(*arg_hint2) : std::get<1>(*arg_hint1),
        std::get<2>(*arg_hint1) || std::get<2>(*arg_hint2),
        std::get<3>(*arg_hint1) || std::get<3>(*arg_hint2),
        std::get<4>(*arg_hint1) || std::get<4>(*arg_hint2)};
}

std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool> ScenarioCompatibilityTable::from_basehint(::cw::lib::String arg_basehint)
{
    return {std::move(arg_basehint), "", false, false, false};
}

::cw::lib::String ScenarioCompatibilityTable::to_basehint(std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> arg_versionhint)
{
    return arg_versionhint ? std::get<0>(*arg_versionhint) : ::cw::lib::String{};
}

std::optional<std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>> ScenarioCompatibilityTable::read_modeini(::cw::lib::String arg_fpath)
{
    try {
        ::cw::lib::ConfigParser config;
        if (!config.read(arg_fpath)) return std::nullopt;
        const auto get = [&](const ::cw::lib::String& key) {
            try { return config.get_required("Compatibility", key); }
            catch (...) { return ::cw::lib::String{}; }
        };
        const auto engine = get("engine"), zindex = get("zIndexMode");
        bool vanish = false;
        try { vanish = ::cw::util::str2bool(get("enableVanishMemberCancellation")); }
        catch (...) { vanish = false; }
        if (!engine.empty() || !zindex.empty() || vanish) return std::tuple<::cw::lib::String, ::cw::lib::String, bool, bool, bool>{engine, zindex, vanish, false, false};
        return {};
    } catch (...) {
        // Py と同様、解析・読み取りの失敗はログに残して情報なしを返す。
        // 上の個別の補間項目の欠落・不正だけで、他の項目まで捨てない。
        ::cw::util::print_ex(std::nullopt);
        return std::nullopt;
    }
}

