    m_write_playlog = boolean("WritePlayLog", m_write_playlog); m_playlogformat = text("PlayLogFormat", m_playlogformat); m_stop_the_world_with_iconized = boolean("StopTheWorldWithIconization", m_stop_the_world_with_iconized); m_open_lastscenario = boolean("OpenLastScenario", m_open_lastscenario); m_open_lastfindresult = boolean("OpenFindScenarioResult", m_open_lastfindresult); m_can_installscenariofromdrop = boolean("CanInstallScenarioFromDrop", m_can_installscenariofromdrop); m_delete_sourceafterinstalled = boolean("DeleteSourceAfterInstalled", m_delete_sourceafterinstalled); m_install_notscenariofiles = boolean("InstallNotScenarioFiles", m_install_notscenariofiles); m_auto_update_files = boolean("AutoUpdateFiles", m_auto_update_files); m_fontexampleformat = text("FontExampleFormat", m_fontexampleformat); m_fontexamplepixelsize = integer("FontExamplePixelSize", m_fontexamplepixelsize);
    m_installed_dir.clear(); if (const auto group = tree->find("InstalledPaths"); group && *group) for (const auto& e : (*group)->m_children) if (e) { const auto rootdir = e->get("root", ""); if (rootdir.empty()) continue; auto& stack = m_installed_dir[rootdir]; for (const auto& p : e->m_children) if (p && !p->get_text().empty()) stack.push_back(p->get_text()); }
    m_bookmarks_for_cardedit.clear(); if (const auto group = tree->find("BookmarksForCardEditor"); group && *group) for (const auto& e : (*group)->m_children) if (e) m_bookmarks_for_cardedit.emplace_back(e->get_text(), e->get("name", ""));
