void Setting::init_skin(std::optional<std::shared_ptr<::cw::data::CWPyElementTree>> arg_basedata)
{
    std::error_code ec;
    // Python版と同じく、起動オプションのskinを一度だけ消費する。
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_OPTIONS.storage()); object && *object) {
        if (const auto options = std::dynamic_pointer_cast<::cw::argparser::ArgResult>(*object)) {
            const auto option_skin = options->getstr("skin");
            options->setstr("skin", "");
            if (!option_skin.empty()) {
                const auto option_path = std::filesystem::u8path("Data/Skin") /
                    std::filesystem::u8path(option_skin) / std::filesystem::u8path("Skin.xml");
                const auto option_status = user_or_native_stat(option_path);
                if (option_status && option_status->is_file()) m_skindirname = option_skin;
            }
        }
    }
    m_skindir = path_utf8(std::filesystem::u8path("Data/Skin") /
                          std::filesystem::u8path(m_skindirname.empty() ? "Classic" : m_skindirname));
    if (m_auto_update_files) ::cw::update::update_files(m_skindir, m_skindirname, std::nullopt);
    auto skin_status = user_or_native_stat(std::filesystem::u8path(m_skindir));
    if (!skin_status || !skin_status->is_directory()) {
        m_skindirname = "Classic";
        m_skindir = path_utf8(std::filesystem::u8path("Data/Skin") / std::filesystem::u8path("Classic"));
        skin_status = user_or_native_stat(std::filesystem::u8path(m_skindir));
        if (!skin_status || !skin_status->is_directory()) {
            const auto skinroot = std::filesystem::u8path("Data/Skin");
            const auto root_status = user_or_native_stat(skinroot);
            if (root_status && root_status->is_directory()) {
                for (const auto& entry : user_or_native_list(skinroot)) {
                    const auto entry_status = user_or_native_stat(entry);
                    const auto candidate = entry / std::filesystem::u8path("Skin.xml");
                    const auto candidate_status = user_or_native_stat(candidate);
                    if (entry_status && entry_status->is_directory() &&
                        candidate_status && candidate_status->is_file()) {
                        m_skindirname = path_utf8(entry.filename());
                        m_skindir = path_utf8(entry);
                        break;
                    }
                }
            }
        }
    }
    skin_status = user_or_native_stat(std::filesystem::u8path(m_skindir));
    if (!skin_status || !skin_status->is_directory())
        throw std::runtime_error("Not found CardWirthPy skins!");
    std::shared_ptr<::cw::data::CWPyElementTree> basedata = arg_basedata.value_or(nullptr);
    if (!basedata) basedata = ::cw::data::xml2etree("Data/SkinBase/Skin.xml", "", std::nullopt, std::nullopt, false);
    const auto skinpath = path_utf8(std::filesystem::u8path(m_skindir) / std::filesystem::u8path("Skin.xml"));
    std::shared_ptr<::cw::data::CWPyElementTree> data;
    try {
        data = _update_skin(skinpath);
    } catch (const std::exception&) {
        ::cw::util::print_ex(std::nullopt);
        const auto native = ::cw::setting::backend();
        if (native && native->show_message) {
            native->show_message("スキンチェックエラー",
                "スキン(" + m_skindirname + ")のロードに失敗しました。\n"
                "スキンのデータが破損している可能性があります。\n"
                "手動での修復を試みるか、スキンを再導入してください。", true);
        }
        // Py はモーダル通知後に、元の読み込み例外を汎用 Exception へ
        // 置き換える。 ネイティブでは runtime_error を対応させる。
        throw std::runtime_error("");
    }
    if (!data) data = basedata;
    if (!data || !data->getroot()) return;
    const auto skin_error = _check_skin();
    m_skindata = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(data));
    if (!skin_error.empty()) {
        const auto native = ::cw::setting::backend();
        if (native && native->show_message)
            native->show_message("スキンチェックエラー", skin_error, true);
        throw std::runtime_error("");
    }
    auto root = data->getroot();
    m_skinname = data->gettext("Property/Name", "");
    m_skintype = data->gettext("Property/Type", "");
    m_vocation120 = XmlReader(*data).getbool("Property/CW120VocationLevel", std::nullopt, false);
    m__classicstyletext = XmlReader(*data).getbool("Property/ClassicStyleText", std::nullopt, false);
    // Py と同様、選択スキンより先に SkinBase の所持金を評価し、解析失敗を伝播させる。
    const auto base_initialcash = basedata ? basedata->getint("Property/InitialCash", std::nullopt, 4000) : 4000;
    m_initialcash = data->getint("Property/InitialCash", std::nullopt, base_initialcash);
    Setting::s_skinname = m_skinname; Setting::s_skintype = m_skintype;
    Setting::s_races.clear();
    if (const auto races = root->find("Races"); races && *races) {
        for (const auto& child : (*races)->m_children) {
            if (!child) continue;
            auto race = std::make_shared<::cw::header::RaceHeader>(); race->initialize(child); Setting::s_races.push_back(std::move(race));
        }
    }
    auto load_features = [&root](const char* tag, auto& out) {
        out.clear();
        const auto group = root->find(tag);
        if (!group || !*group) return;
        for (const auto& child : (*group)->m_children) {
            if (!child) continue;
            auto value = std::make_shared<typename std::decay_t<decltype(out)>::value_type::element_type>();
            value->initialize(child); out.push_back(std::move(value));
        }
    };
    load_features("Sexes", Setting::s_sexes); load_features("Periods", Setting::s_periods);
    load_features("Natures", Setting::s_natures); load_features("Makings", Setting::s_makings);
    load_features("SampleTypes", Setting::s_sampletypes);
    if (basedata && basedata->getroot()) {
        std::map<::cw::lib::String, ::cw::lib::String> sample_desc;
        if (const auto base_samples = basedata->find("SampleTypes"); base_samples && *base_samples) for (const auto& child : (*base_samples)->m_children) if (child) { const auto name = child->gettext("Name", ""); if (!name.empty()) sample_desc[name] = ::cw::util::decodewrap(child->gettext("Description", "")); }
        for (const auto& sample : Setting::s_sampletypes) if (sample && sample->m_description.empty()) sample->m_description = sample_desc[sample->m_name];
    }
    Setting::s_sexnames.clear(); Setting::s_sexsubnames.clear(); Setting::s_sexcoupons.clear();
    for (const auto& item : Setting::s_sexes) { if (!item) continue; Setting::s_sexnames.push_back(item->m_name); Setting::s_sexsubnames.push_back(item->m_subname); Setting::s_sexcoupons.push_back("＿" + item->m_name); }
    Setting::s_periodnames.clear(); Setting::s_periodcoupons.clear();
    std::vector<::cw::lib::String> periodsubnames;
    for (const auto& item : Setting::s_periods) { if (!item) continue; Setting::s_periodnames.push_back(item->m_name); periodsubnames.push_back(item->m_subname); Setting::s_periodcoupons.push_back("＿" + item->m_name); }
    auto period_values = std::make_shared<::cw::data::VariantSequence>(); for (const auto& value : periodsubnames) period_values->m_values.emplace_back(value); m_periodsubnames = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(period_values));
    Setting::s_naturenames.clear(); Setting::s_naturecoupons.clear();
    for (const auto& item : Setting::s_natures) { if (!item) continue; Setting::s_naturenames.push_back(item->m_name); Setting::s_naturecoupons.push_back("＿" + item->m_name); }
    Setting::s_makingnames.clear(); Setting::s_makingcoupons.clear();
    for (const auto& item : Setting::s_makings) { if (!item) continue; Setting::s_makingnames.push_back(item->m_name); Setting::s_makingcoupons.push_back("＿" + item->m_name); }
    m_skinsyscoupons = std::make_shared<SystemCoupons>();
    const auto coupons = root->find("SystemCoupons");
    m_skinsyscoupons->initialize({}, coupons && *coupons ? std::optional<std::shared_ptr<::cw::data::CWPyElement>>(*coupons) : std::nullopt);
    // Skin側の定義をSkinBase→選択Skinの順に重ねる（後勝ち）。
    // Python版の辞書をValueMap/MsgDictへ展開し、空要素を作らない。
    m_sound_table.clear();
    m_msgs = std::make_shared<MsgDict>();
    auto merge_skin_tables = [this](const std::shared_ptr<::cw::data::CWPyElement>& source) {
        if (!source) return;
        if (const auto sounds = source->find("Sounds"); sounds && *sounds) {
            for (const auto& element : (*sounds)->m_children) {
                if (!element) continue;
                const auto key = element->get("key", "");
                if (!key.empty()) m_sound_table[key] = ::cw::lib::Value(element->get_text());
            }
        }
        if (const auto messages = source->find("Messages"); messages && *messages) {
            for (const auto& element : (*messages)->m_children) {
                if (!element) continue;
                const auto key = element->get("key", "");
                if (!key.empty()) m_msgs->set_item(key, element->get_text());
            }
        }
    };
    if (basedata) merge_skin_tables(basedata->getroot());
    merge_skin_tables(root);
    Setting::s_msgs = m_msgs;
    auto unknown = std::make_shared<::cw::header::UnknownRaceHeader>();
    auto self = std::shared_ptr<::cw::setting::Setting>(this, [](Setting*) {});
    unknown->initialize(self); m_unknown_race = unknown; Setting::s_unknown_race = unknown; Setting::s_races.push_back(std::static_pointer_cast<::cw::header::RaceHeader>(unknown));
    const auto local = root->find("Settings");
    if (local && *local) m_skin_local->load(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*local)));
    else m_skin_local = m_local->copy();
}

std::shared_ptr<::cw::data::CWPyElementTree> Setting::_update_skin(::cw::lib::String arg_path)
{
    const auto mutex_dir = path_utf8(std::filesystem::u8path(arg_path).parent_path());
    while (!::cw::util::create_mutex(mutex_dir)) std::this_thread::sleep_for(std::chrono::milliseconds(1));
    return ::cw::lib::finally_call([&]() -> std::shared_ptr<::cw::data::CWPyElementTree> {
    auto data = ::cw::data::xml2etree(arg_path, "", std::nullopt, std::nullopt, false);
    if (!data || !data->getroot()) return {};
    auto root = data->getroot();
    double version = 0.0; parse_python_float(root->get("dataVersion", "0"), version);
    bool updated = false;
    if (version <= 1.0) {
        // dataVersion=1以前はMentalのcautious/cheerfulが逆で、各値が半分だった。
        const auto update_mental = [](const std::shared_ptr<::cw::data::CWPyElement>& element) {
            if (!element) return;
            const auto mental = element->find("Mental");
            if (!mental || !*mental) return;
            const auto cautious = (*mental)->get("cautious", "");
            const auto cheerful = (*mental)->get("cheerful", "");
            (*mental)->set("cautious", cheerful); (*mental)->set("cheerful", cautious);
        };
        for (const auto* tag : {"Sexes", "Periods", "Natures", "Makings"}) {
            const auto group = root->find(tag);
            if (group && *group) for (const auto& element : (*group)->m_children) update_mental(element);
        }
        const auto sampletypes = root->find("SampleTypes");
        if (sampletypes && *sampletypes) {
            const std::array<std::tuple<const char*, double, double>, 5> base_samples{{
                {"バランス", 0.0, 0.0}, {"ファイター", -0.5, 0.0}, {"シーフ", 0.5, 0.0},
                {"プリースト", 0.0, 0.5}, {"メイジ", 0.5, -0.5}}};
            bool is_base = (*sampletypes)->m_children.size() == base_samples.size();
            if (is_base) {
                for (std::size_t i = 0; i < base_samples.size(); ++i) {
                    const auto& element = (*sampletypes)->m_children[i];
                    const auto mental = element ? element->find("Mental") : std::nullopt;
                    double cautious = 0.0, cheerful = 0.0;
                    if (!element || element->gettext("Name", "") != std::get<0>(base_samples[i]) || !mental || !*mental ||
                        !parse_python_float((*mental)->get("cautious", ""), cautious) ||
                        !parse_python_float((*mental)->get("cheerful", ""), cheerful) ||
                        std::abs(cautious - std::get<1>(base_samples[i])) >= 1e-9 ||
                        std::abs(cheerful - std::get<2>(base_samples[i])) >= 1e-9) { is_base = false; break; }
                }
            }
            if (!is_base) for (const auto& element : (*sampletypes)->m_children) update_mental(element);
            for (const auto& element : (*sampletypes)->m_children) {
                const auto mental = element ? element->find("Mental") : std::nullopt;
                if (!mental || !*mental) continue;
                for (const auto* key : {"aggressive", "brave", "cautious", "cheerful", "trickish"}) {
                    double value = 0.0;
                    if (parse_python_float((*mental)->get(key, ""), value)) (*mental)->set(key, std::to_string(value * 2.0));
                }
            }
        }
        updated = true;
    }
    if (version <= 5.0) {
        // v5以前の単純なPostEventをMenuCardの属性へ移し、変換前の
        // Resource/Xmlを_vNへ退避する（Python版と同じく4カテゴリを対象）。
        const auto suffix = version == std::floor(version)
            ? std::to_string(static_cast<int>(version)) : ::cw::lib::python_float_repr(version);
        for (const auto* name : {"GameOver", "Scenario", "Title", "Yado"}) {
            const auto directory = std::filesystem::u8path(m_skindir) / "Resource/Xml" / name;
            if (!std::filesystem::is_directory(directory)) continue;
            std::error_code copy_ec; const auto backup = ::cw::util::dupcheck_plus(path_utf8(directory) + "_v" + suffix, false, false);
            std::filesystem::copy(directory, std::filesystem::u8path(backup), std::filesystem::copy_options::recursive, copy_ec);
            for (const auto& entry : std::filesystem::directory_iterator(directory, copy_ec)) {
                if (copy_ec || !entry.is_regular_file(copy_ec) ||
                    ::cw::lib::encoding::python_lower(path_utf8(entry.path().extension())) != ".xml") continue;
                const auto fpath = path_utf8(entry.path()); auto tree = ::cw::data::xml2etree(fpath, "", std::nullopt, std::nullopt, false); if (!tree) continue;
                bool changed = false; const auto cards = tree->find("MenuCards");
                if (cards && *cards) for (const auto& card : (*cards)->m_children) {
                    if (!card) continue; const auto events = card->find("Events"); if (!events || !*events || (*events)->m_children.size() != 1) continue;
                    const auto event = (*events)->m_children.front(); if (!event) continue;
                    const auto ignitions = event->find("Ignitions"); if (!ignitions || !*ignitions || (*ignitions)->gettext("Number", "") != "1" || !(*ignitions)->gettext("KeyCodes", "").empty()) continue;
                    const auto post = event->find("Contents/Start/Contents/Post"); if (!post || !*post || (*post)->get("type", "") != "Event") continue;
                    const auto command = (*post)->get("command", ""); if (command.empty()) continue; card->set("command", command); const auto arg = (*post)->get("arg", ""); if (!arg.empty()) card->set("arg", arg); (*events)->clear(); changed = true;
                }
                if (changed) tree->write_file(fpath);
            }
        }
        updated = true;
    }
    if (version <= 6.0) {
        const auto fpath = std::filesystem::u8path(m_skindir) / "Resource/Xml/ActionCard/-1_Confuse.xml";
        if (std::filesystem::is_regular_file(fpath)) {
            const auto suffix = version == std::floor(version)
                ? std::to_string(static_cast<int>(version)) : ::cw::lib::python_float_repr(version);
            const auto backup = ::cw::util::dupcheck_plus(path_utf8(fpath) + ".v" + suffix, false, false);
            std::error_code copy_ec; std::filesystem::copy_file(fpath, std::filesystem::u8path(backup), std::filesystem::copy_options::none, copy_ec);
            auto tree = ::cw::data::xml2etree(path_utf8(fpath), "", std::nullopt, std::nullopt, false); if (tree) {
                const auto enhance = tree->find("Property/Enhance"); if (enhance && *enhance) { if ((*enhance)->get("avoid", "-10") == "-5") (*enhance)->set("avoid", "-10"); if ((*enhance)->get("resist", "-10") == "-5") (*enhance)->set("resist", "-10"); tree->write_file(path_utf8(fpath)); }
            }
        }
        updated = true;
    }
    if (version <= 8.0) {
        // タイトル画面の旧配置を新位置へ補正。
        const auto title = std::filesystem::u8path(m_skindir) / "Resource/Xml/Title/01_Title.xml";
        if (std::filesystem::is_regular_file(title)) {
            auto tree = ::cw::data::xml2etree(path_utf8(title), "", std::nullopt, std::nullopt, false); if (tree) {
                const auto cards = tree->find("MenuCards"); if (cards && *cards && (*cards)->m_children.size() == 2 && (*cards)->get("spreadtype", "") == "Custom") {
                    const auto a = (*cards)->m_children[0], b = (*cards)->m_children[1]; const auto al = a->find("Property/Location"), bl = b->find("Property/Location");
                    if (al && *al && bl && *bl && (*al)->get("left", "") == "231" && (*al)->get("top", "") == "156" && (*bl)->get("left", "") == "316" && (*bl)->get("top", "") == "156") {
                        // Python版は変更前XMLを .vN として退避してから書き換える。
                        const auto suffix = version == std::floor(version)
                            ? std::to_string(static_cast<int>(version)) : ::cw::lib::python_float_repr(version);
                        const auto backup = ::cw::util::dupcheck_plus(path_utf8(title) + ".v" + suffix, false, false);
                        std::error_code backup_ec;
                        std::filesystem::copy_file(title, std::filesystem::u8path(backup), std::filesystem::copy_options::none, backup_ec);
                        (*al)->set("left", "233"); (*al)->set("top", "150"); (*bl)->set("left", "318"); (*bl)->set("top", "150"); tree->write_file(path_utf8(title));
                    }
                }
            }
        }
        const auto initial = std::filesystem::u8path(m_skindir) / "Resource/Xml/Yado/03_YadoInitial.xml";
        if (!std::filesystem::is_regular_file(initial)) {
            const auto source = std::filesystem::u8path("Data/SkinBase/Resource/Xml/Yado/03_YadoInitial.xml"); std::error_code copy_ec; std::filesystem::create_directories(initial.parent_path(), copy_ec); std::filesystem::copy_file(source, initial, std::filesystem::copy_options::none, copy_ec);
            if (!copy_ec && std::filesystem::is_regular_file(initial)) {
                // 旧01_Yado.xmlのプレイヤー選択/タイトル復帰カードと
                // BgImages/Eventsを初期宿へ移植する。
                const auto yado = std::filesystem::u8path(m_skindir) / "Resource/Xml/Yado/01_Yado.xml";
                if (std::filesystem::is_regular_file(yado)) {
                    auto initial_tree = ::cw::data::xml2etree(path_utf8(initial), "", std::nullopt, std::nullopt, false);
                    auto yado_tree = ::cw::data::xml2etree(path_utf8(yado), "", std::nullopt, std::nullopt, false);
                    if (initial_tree && initial_tree->getroot() && yado_tree && yado_tree->getroot()) {
                        const auto initial_root = initial_tree->getroot(); const auto yado_root = yado_tree->getroot();
                        const auto initial_cards = initial_root->find("MenuCards"); const auto yado_cards = yado_root->find("MenuCards");
                        std::shared_ptr<::cw::data::CWPyElement> player_select; std::shared_ptr<::cw::data::CWPyElement> return_title;
                        if (yado_cards && *yado_cards) for (const auto& card : (*yado_cards)->m_children) {
                            if (!card) continue;
                            const auto command = card->get("command", ""); const auto arg = card->get("arg", "");
                            if (command == "ShowDialog" && arg == "PLAYERSELECT") player_select = card;
                            else if (command == "ShowDialog" && arg == "RETURNTITLE") return_title = card;
                        }
                        const auto copy_card_property = [](const std::shared_ptr<::cw::data::CWPyElement>& source,
                                                           const std::shared_ptr<::cw::data::CWPyElement>& destination) {
                            if (!source || !destination) return;
                            for (const auto* path : {"Name", "ImagePath", "Description"}) {
                                const auto value = source->gettext("Property/" + ::cw::lib::String(path), "");
                                const auto property = destination->find("Property/" + ::cw::lib::String(path));
                                if (property && *property) (*property)->set_text(value);
                            }
                        };
                        if (initial_cards && *initial_cards && (*initial_cards)->m_children.size() >= 2) {
                            copy_card_property(player_select, (*initial_cards)->m_children[0]);
                            copy_card_property(return_title, (*initial_cards)->m_children[1]);
                        }
                        if (const auto bgimgs = yado_root->find("BgImages"); bgimgs && *bgimgs) {
                            const auto existing = initial_root->find("BgImages"); if (existing && *existing) initial_root->remove(*existing);
                            yado_root->remove(*bgimgs); initial_root->insert(1, *bgimgs);
                        }
                        if (const auto events = yado_root->find("Events"); events && *events) {
                            const auto existing = initial_root->find("Events"); if (existing && *existing) initial_root->remove(*existing);
                            yado_root->remove(*events); initial_root->append(*events);
                        }
                        initial_tree->write_file(path_utf8(initial));
                    }
                }
            }
        }
        updated = true;
    }
    if (version <= 9.0) {
        const auto opening = std::filesystem::u8path(m_skindir) / "Resource/Xml/Animation/Opening.xml";
        if (!std::filesystem::is_regular_file(opening)) {
            const auto source = std::filesystem::u8path("Data/SkinBase/Resource/Xml/Animation/Opening.xml");
            if (!std::filesystem::is_directory(opening.parent_path()))
                std::filesystem::create_directories(opening.parent_path());
            std::filesystem::copy_file(source, opening, std::filesystem::copy_options::overwrite_existing);
            // shutil.copy2 の共通部分である更新時刻・権限をここで維持する。
            // std::filesystem では追加の OS メタデータは保持できない
            // 。 コピーの失敗はすべて、新しいスキンバージョンを公開する前に伝播させる。
            std::filesystem::last_write_time(opening, std::filesystem::last_write_time(source));
            std::filesystem::permissions(opening, std::filesystem::status(source).permissions());
        }
        updated = true;
    }
    if (version <= 11.0) {
        const auto property = root->find("Property");
        if (property && *property && data->gettext("Property/Type", "") == "School") {
            const auto chime = std::filesystem::u8path(m_skindir) / std::filesystem::u8path("Bgm/chime.mp3");
            if (std::filesystem::is_regular_file(chime)) {
                if (!(*property)->find("SourceOfMaterialsIsClassicEngine")) {
                    (*property)->append(::cw::data::make_element("SourceOfMaterialsIsClassicEngine", "True"));
                    updated = true;
                }
            }
        }
    }
    if (updated) { root->set("dataVersion", "12"); data->write_file(arg_path); }
    return data;
    }, [] { ::cw::util::release_mutex(); });
}

::cw::lib::String Setting::_check_skin()
{
    const auto yado = std::filesystem::u8path(m_skindir) / std::filesystem::u8path("Resource/Xml/Yado");
    const auto yado_status = user_or_native_stat(yado);
    if (!yado_status || !yado_status->is_directory()) return path_utf8(yado) + "が見つかりません。";
    bool has_initial_area = false;
    for (const auto& entry : user_or_native_list(yado)) {
        ::cw::header::GetName id;
        id.initialize(path_utf8(entry), "Id");
        const auto normalized = ::cw::lib::normalize_python_integer(id.m_name);
        if (!normalized) throw std::invalid_argument("invalid skin area Id: " + id.m_name);
        // 必要なのは 3 との等価比較だけである。 ネイティブ範囲外の有効な
        // Python 整数は 3 と一致しないため、解析エラーにはしない。
        const auto value = ::cw::lib::parse_python_integer(*normalized);
        if (value && *value == 3) { has_initial_area = true; break; }
    }
    if (!has_initial_area) return "スキンにデータバージョン「9」で導入された「初期拠点」エリアが存在しません。\n"
        "スキンの自動アップデートに失敗した可能性があります。\n"
        "手動での修復を試みるか、スキンを再導入してください。";
    const auto opening = std::filesystem::u8path(m_skindir) / std::filesystem::u8path("Resource/Xml/Animation/Opening.xml");
    const auto opening_status = user_or_native_stat(opening);
    if (!opening_status || !opening_status->is_file()) return "スキンにデータバージョン「10」で導入されたオープニングアニメーション定義が存在しません。\n"
        "スキンの自動アップデートに失敗した可能性があります。\n"
        "手動での修復を試みるか、スキンを再導入してください。";
    return {};
}

void Setting::set_dealspeed(::cw::lib::Integer arg_value, ::cw::lib::Integer arg_battlevalue, bool arg_usebattle)
{
    m_dealspeed = std::clamp(arg_value, ::cw::lib::Integer{0}, ::cw::lib::Integer{10});
    m_dealspeed_battle = std::clamp(arg_battlevalue, ::cw::lib::Integer{0}, ::cw::lib::Integer{10});
    auto scales = std::make_shared<::cw::data::VariantSequence>(); const auto count = m_dealspeed + 1; for (::cw::lib::Integer i = 1; i < count; ++i) scales->m_values.emplace_back(static_cast<::cw::lib::Integer>(std::cos(3.14159265358979323846 * 0.5 * static_cast<double>(i) / static_cast<double>(count)) * 100.0)); m_dealing_scales = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(scales));
    auto battle = std::make_shared<::cw::data::VariantSequence>(); const auto battle_count = m_dealspeed_battle + 1; for (::cw::lib::Integer i = 1; i < battle_count; ++i) battle->m_values.emplace_back(static_cast<::cw::lib::Integer>(std::cos(3.14159265358979323846 * 0.5 * static_cast<double>(i) / static_cast<double>(battle_count)) * 100.0)); m_dealing_scales_battle = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(battle));
    m_use_battlespeed = arg_usebattle;
}

::cw::lib::Integer Setting::get_dealspeed(bool arg_isbattle)
{
    return arg_isbattle && m_use_battlespeed ? m_dealspeed_battle : m_dealspeed;
}

std::vector<::cw::lib::Integer> Setting::create_dealingscales(::cw::lib::Integer arg_dealspeed)
{
    arg_dealspeed = std::clamp(arg_dealspeed, ::cw::lib::Integer{0}, ::cw::lib::Integer{10}); std::vector<::cw::lib::Integer> result; const auto count = arg_dealspeed + 1; for (::cw::lib::Integer i = 1; i < count; ++i) result.push_back(static_cast<::cw::lib::Integer>(std::cos(3.14159265358979323846 * 0.5 * static_cast<double>(i) / static_cast<double>(count)) * 100.0)); return result;
}

