std::map<::cw::lib::String, std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool>> Setting::get_fonttypes()
{
    auto local = get_fontsetting();
    auto result = local->m_fonttypes_typed;
    // 型付きの行は基本フォントの種別と具体的な書体を区
    // 別できるため、正本とする。 旧スカラー形式では区
    // 別できないので、型付き設定にない行だけを補う。
    for (const auto& [name, value] : local->m_fonttypes) {
        if (const auto* face = std::get_if<::cw::lib::String>(&value.storage())) {
            auto it = result.find(name);
            if (it == result.end()) result[name] = {*face, "", 22, true, true, false};
        }
    }
    return result;
}

