void Setting::update_soundfonts()
{
    // SettingsPanel::applyは既存UIとの互換のためm_soundfonts(Value)を
    // 直接差し替える。ObjectがSoundFontTableなら必ず型付き正本へ同期し、
    // 空のSoundFontsも「全行削除」として保持する。
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_soundfonts.storage()); object && *object) {
        if (const auto table = std::dynamic_pointer_cast<::cw::dialog::settings::SoundFontTable>(*object))
            m_soundfonts_typed = table->m_rows;
    }
    if (m_soundfonts_typed.empty() && !m_soundfonts_init_typed.empty()) {
        // 不正なValueを設定された場合だけ既定値へ戻す。正規の空表は
        // SoundFontTableオブジェクトから同期済みなのでこの分岐に入らない。
        if (!std::get_if<::cw::lib::ObjectPtr>(&m_soundfonts.storage()))
            m_soundfonts_typed = m_soundfonts_init_typed;
    }
    m_soundfonts = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(make_soundfont_table(m_soundfonts_typed)));

    // この関数は XML の読み込み・書き出しでも使うため、表の同期だ
    // けを行う。 実行中の MIDI バックエンドを再設定できるのは、
    // SettingsPanel の確定した実体への適用だけとする。
}

void Setting::write()
{
    update_soundfonts();
    std::shared_ptr<::cw::data::CWPyElementTree> tree;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m_data.storage()); object && *object)
        tree = std::dynamic_pointer_cast<::cw::data::CWPyElementTree>(*object);
    if (!tree) {
        auto path = std::filesystem::u8path("Settings.xml");
        if (const auto mounted = ::cardwirth::platform::resolve_mounted_user_path(path))
            path = *mounted;
        tree = std::make_shared<::cw::data::CWPyElementTree>(
            ::cw::data::make_element("Settings", "",
                std::map<::cw::lib::String, ::cw::lib::String>{{"dataVersion", "4"}}),
            ::cw::lib::encoding::path_to_utf8(path));
    }
    // 通常保存と設定の書き出しで、Python の create_settings の規則を共有する。
    tree->m_root_node = ::cw::xmlcreater::settings_element(*this, true);
    // Python版Setting.write()は常に標準のSettings.xmlへ保存する。
    if (!tree->m_user_storage_backed) tree->m_fpath = "Settings.xml";
    tree->write_file(tree->m_fpath);
    m_data = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(tree));
}

::cw::lib::Real Setting::wrap_volumevalue(::cw::lib::Integer arg_value)
{
    return static_cast<::cw::lib::Real>(std::clamp(arg_value, ::cw::lib::Integer{0}, ::cw::lib::Integer{100})) / 100.0;
}

std::tuple<::cw::lib::Integer, ::cw::lib::Integer, ::cw::lib::Integer, ::cw::lib::Integer> Setting::wrap_colorvalue(::cw::lib::Integer arg_r, ::cw::lib::Integer arg_g, ::cw::lib::Integer arg_b, ::cw::lib::Integer arg_a)
{
    return {std::clamp(arg_r, ::cw::lib::Integer{0}, ::cw::lib::Integer{255}), std::clamp(arg_g, ::cw::lib::Integer{0}, ::cw::lib::Integer{255}), std::clamp(arg_b, ::cw::lib::Integer{0}, ::cw::lib::Integer{255}), std::clamp(arg_a, ::cw::lib::Integer{0}, ::cw::lib::Integer{255})};
}

::cw::lib::String Setting::get_scedir(std::optional<::cw::lib::String> arg_skintype)
{
    const auto type = arg_skintype.value_or(m_skintype);
    if (m_selectscenariofromtype) {
        for (const auto& [skintype, folder] : m_folderoftype) {
            if (skintype != type) continue;
            auto path = std::filesystem::u8path(folder);
            if (const auto mounted = ::cardwirth::platform::resolve_mounted_user_path(path))
                path = *mounted;
            path = std::filesystem::u8path(::cw::util::get_linktarget(path_utf8(path)));
            const auto status = user_or_native_stat(path);
            if (status && status->is_directory()) return path_utf8(path);
            // Py と同様、最初に一致した種別で止める。 そのフォルダ
            // ーが空・欠落・通常ファイルでも、後の重複で上書きしない。
            break;
        }
    }
    auto path = std::filesystem::u8path("Scenario");
    if (const auto mounted = ::cardwirth::platform::resolve_mounted_user_path(path))
        path = *mounted;
    return path_utf8(path);
}

void Setting::insert_yadoorder(::cw::lib::String arg_yadodirname)
{
    std::vector<std::pair<::cw::lib::Integer, ::cw::lib::String>> ordered;
    ordered.reserve(m_yado_order.size());
    for (const auto& [name, order] : m_yado_order) ordered.emplace_back(order, name);
    std::sort(ordered.begin(), ordered.end());
    m_yado_order.clear();
    m_yado_order[arg_yadodirname] = 0;
    ::cw::lib::Integer next = 1;
    for (const auto& [order, name] : ordered) {
        (void)order;
        if (name == arg_yadodirname) continue;
        m_yado_order[name] = next++;
    }
}

void SystemCoupons::initialize(::cw::lib::String arg_fpath, std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_data)
{
    m__normal.clear();
    m__regexes.clear();
    m__uc_normal.clear();
    m__uc_regexes.clear();
    m__ats = true;
    // Python版は渡されたElementを優先し、無い場合だけSystemCoupons.xmlを読む。
    std::shared_ptr<::cw::data::CWPyElement> root;
    if (arg_data && *arg_data) {
        root = *arg_data;
    } else if (::cw::util::path_is_file(arg_fpath)) {
        const auto tree = ::cw::data::xml2etree(arg_fpath, "", std::nullopt, std::nullopt, false);
        if (tree) root = tree->getroot();
    }
    if (!root) return;

    // クーポン要素はファイルのルート直下に並ぶ。未知のタグもPython版と
    // 同様に要素テキストだけを規則として扱い、空文字もそのまま登録する。
    for (const auto& element : root->m_children) {
        if (!element) continue;
        auto coupon = element->get_text();
        if (m__ats && coupon.rfind("＠", 0) != 0) m__ats = false;

        const auto method = element->get("method", "Normal");
        const bool unconditional = method == "UnconditionalSuccess";
        const bool is_regex = element->getbool(".", ::cw::lib::Value("regex"), false);
        if (is_regex) {
            // Python の re の文法と Unicode 文字クラスを維持する。
            // 特に \Z は Python の $ と異なり、厳密な文字列終端を表す。
            auto& regexes = unconditional ? m__uc_regexes : m__regexes;
            regexes.push_back(std::make_shared<::cw::lib::python_re::Pattern>(coupon));
        } else {
            auto& normal = unconditional ? m__uc_normal : m__normal;
            normal.insert(std::move(coupon));
        }
    }
}

bool SystemCoupons::unconditional_match(::cw::lib::String arg_coupon)
{
    return _match_impl(arg_coupon, m__uc_normal, m__uc_regexes);
}

bool SystemCoupons::match(::cw::lib::String arg_coupon)
{
    return _match_impl(arg_coupon, m__normal, m__regexes);
}

bool SystemCoupons::_match_impl(const ::cw::lib::String& arg_coupon, const std::set<::cw::lib::String>& arg_normal, const std::vector<std::shared_ptr<::cw::lib::python_re::Pattern>>& arg_regexes) const
{
    if (m__ats && arg_coupon.rfind("＠", 0) != 0) return false;
    if (arg_normal.contains(arg_coupon)) return true;
    return std::any_of(arg_regexes.begin(), arg_regexes.end(), [&](const auto& pattern) {
        return pattern->match(arg_coupon);
    });
}

